  review_note, content_hash) values
  ('igcse.biology', 'cells', 'igcse.biology/cells/cell-structure', 'mcq', null, 'Mitochondria are responsible for:', '[{"text":"Protein synthesis"},{"text":"Cell division"},{"text":"Energy production (ATP)"},{"text":"DNA storage"}]'::jsonb, 2, 'Mitochondria produce ATP via aerobic respiration. They''re called the ''powerhouse of the cell''.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '5bbc353e14bceaa48622c1fd21acb863'),
  ('igcse.biology', 'cells', 'igcse.biology/cells/cell-structure', 'mcq', null, 'Cell walls are found in:', '[{"text":"Animal cells"},{"text":"Both plant and animal cells"},{"text":"Neither"},{"text":"Plant cells only"}]'::jsonb, 3, 'Plant cells have cell walls made of cellulose. Animal cells have only a cell membrane.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'aa0ca9625f91bb818a12a610b2012f4f'),
  ('igcse.biology', 'cells', 'igcse.biology/cells/enzymes', 'mcq', null, 'Enzymes function as:', '[{"text":"Energy sources"},{"text":"Structural proteins"},{"text":"Biological catalysts"},{"text":"Transport molecules"}]'::jsonb, 2, 'Enzymes are biological catalysts — they speed up reactions without being consumed. They are specific to their substrate.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '32c51d1bf9739ba60c285d7a3dee1089'),
  ('igcse.biology', 'cells', 'igcse.biology/cells/cell-structure', 'mcq', null, 'The control centre of a cell is the:', '[{"text":"Ribosome"},{"text":"Nucleus"},{"text":"Vacuole"},{"text":"Cell wall"}]'::jsonb, 1, 'The nucleus contains DNA and controls cell activities.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'b0fbd703908199bdec55b06c63d50b2d'),
  ('igcse.biology', 'cells', 'igcse.biology/cells/cell-structure', 'mcq', null, 'Photosynthesis occurs in the:', '[{"text":"Mitochondria"},{"text":"Chloroplast"},{"text":"Nucleus"},{"text":"Ribosome"}]'::jsonb, 1, 'Chloroplasts contain chlorophyll and carry out photosynthesis in plant cells.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '634aaea834a80479e1987d47a7b2e530'),
  ('igcse.biology', 'cells', 'igcse.biology/cells/cell-structure', 'mcq', null, 'Ribosomes are the site of:', '[{"text":"Respiration"},{"text":"Protein synthesis"},{"text":"Photosynthesis"},{"text":"Digestion"}]'::jsonb, 1, 'Ribosomes assemble amino acids into proteins.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '9c9e87091a87c8303ce673c5318dc57f'),
  ('igcse.biology', 'cells', 'igcse.biology/cells/cell-structure', 'mcq', null, 'Which structure is found in plant cells but NOT animal cells?', '[{"text":"Nucleus"},{"text":"Cell wall"},{"text":"Mitochondria"},{"text":"Ribosome"}]'::jsonb, 1, 'Cell walls (cellulose) are present in plant cells, absent in animal cells.', 3, 'recall', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '0a77ba479288739da17fa068c8815523'),
  ('igcse.biology', 'cells', 'igcse.biology/cells/transport-membranes', 'mcq', null, 'Diffusion is the movement of particles from:', '[{"text":"Low to high concentration"},{"text":"High to low concentration"},{"text":"Cold to hot"},{"text":"Inside to outside only"}]'::jsonb, 1, 'Diffusion moves particles down a concentration gradient (high → low).', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'f551dc158bfa52e41a5e9bfb71fa48cb'),
  ('igcse.biology', 'cells', 'igcse.biology/cells/cell-structure', 'mcq', null, 'The cell membrane is described as:', '[{"text":"Fully permeable"},{"text":"Partially (selectively) permeable"},{"text":"Impermeable"},{"text":"Solid"}]'::jsonb, 1, 'The membrane is partially permeable, controlling what enters and leaves.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '51d08905c891030f3beb279bc73bae80'),
  ('igcse.biology', 'cells', 'igcse.biology/cells/cell-structure', 'mcq', null, 'Mitochondria release energy through:', '[{"text":"Photosynthesis"},{"text":"Aerobic respiration"},{"text":"Diffusion"},{"text":"Mitosis"}]'::jsonb, 1, 'Mitochondria carry out aerobic respiration, releasing ATP energy.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '560726d1c6eb63a6bb2aceae18866608'),
  ('igcse.biology', 'human-biology', 'igcse.biology/human-biology/circulation', 'mcq', null, 'How many chambers does the human heart have?', '[{"text":"2"},{"text":"6"},{"text":"3"},{"text":"4"}]'::jsonb, 3, 'The heart has 4 chambers: left/right atria (upper) and left/right ventricles (lower).', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'ffbb38625ae74fcce09e580b89349ece'),
  ('igcse.biology', 'human-biology', 'igcse.biology/human-biology/nutrition-digestion', 'mcq', null, 'Insulin is produced by the:', '[{"text":"Liver"},{"text":"Stomach"},{"text":"Kidney"},{"text":"Pancreas"}]'::jsonb, 3, 'Beta cells in the pancreatic islets of Langerhans produce insulin, which lowers blood glucose.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '48622e2fa7280fc3e2f764b450b9082e'),
  ('igcse.biology', 'human-biology', 'igcse.biology/human-biology/circulation', 'mcq', null, 'The largest organ of the human body is:', '[{"text":"Heart"},{"text":"Liver"},{"text":"Brain"},{"text":"Skin"}]'::jsonb, 3, 'Skin is the largest organ by area (~2m²) and weight. It provides protection, temperature regulation, and sensation.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'd9bbce7b13e7edaf1b731fd40f21f5e8'),
  ('igcse.biology', 'human-biology', 'igcse.biology/human-biology/circulation', 'mcq', null, 'Antibodies are produced by:', '[{"text":"Red blood cells"},{"text":"Platelets"},{"text":"Neutrophils"},{"text":"B lymphocytes"}]'::jsonb, 3, 'B lymphocytes (B cells) differentiate into plasma cells which produce antibodies (immunoglobulins) specific to antigens.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '791c361304094d8f54ea02b6ad91c321'),
  ('igcse.biology', 'human-biology', 'igcse.biology/human-biology/circulation', 'mcq', null, 'Oxygen is carried in the blood by:', '[{"text":"Plasma only"},{"text":"Red blood cells (haemoglobin)"},{"text":"White blood cells"},{"text":"Platelets"}]'::jsonb, 1, 'Haemoglobin in red blood cells binds and transports oxygen.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '97a495e043a77b30f36e4c2bf4470b21'),
  ('igcse.biology', 'human-biology', 'igcse.biology/human-biology/homeostasis-disease', 'mcq', null, 'The main function of white blood cells is to:', '[{"text":"Carry oxygen"},{"text":"Fight infection"},{"text":"Clot blood"},{"text":"Store fat"}]'::jsonb, 1, 'White blood cells defend against pathogens (engulfing them or making antibodies).', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '9413cb23cc33d21b82a14f4bb0786702'),
  ('igcse.biology', 'human-biology', 'igcse.biology/human-biology/nutrition-digestion', 'mcq', null, 'Where does most nutrient absorption occur?', '[{"text":"Stomach"},{"text":"Small intestine"},{"text":"Large intestine"},{"text":"Mouth"}]'::jsonb, 1, 'The small intestine (villi) absorbs most digested nutrients into the blood.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'cd2d77473f06903d5d3b5784ffd06f22'),
  ('igcse.biology', 'human-biology', 'igcse.biology/human-biology/gas-exchange', 'mcq', null, 'The breathing gas exchanged INTO the blood in the lungs is:', '[{"text":"Carbon dioxide"},{"text":"Oxygen"},{"text":"Nitrogen"},{"text":"Hydrogen"}]'::jsonb, 1, 'Oxygen diffuses into the blood in the alveoli; CO₂ diffuses out.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '53c5f90eaeaca99809b48651c4ffdaef'),
  ('igcse.biology', 'human-biology', 'igcse.biology/human-biology/circulation', 'mcq', null, 'Insulin lowers blood glucose and is made by the:', '[{"text":"Liver"},{"text":"Pancreas"},{"text":"Kidney"},{"text":"Heart"}]'::jsonb, 1, 'The pancreas releases insulin, which lowers blood glucose.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '92e44ca864953a9704f0aeda96981f49'),
  ('igcse.biology', 'human-biology', 'igcse.biology/human-biology/coordination', 'mcq', null, 'The nervous system''s basic cell is the:', '[{"text":"Neuron"},{"text":"Nephron"},{"text":"Alveolus"},{"text":"Villus"}]'::jsonb, 0, 'Neurons transmit electrical impulses through the nervous system.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'c5ad613ca015bf93dd8ae834f0a449c0'),
  ('igcse.biology', 'human-biology', 'igcse.biology/human-biology/homeostasis-disease', 'mcq', null, 'The largest organ of the human body is the:', '[{"text":"Liver"},{"text":"Skin"},{"text":"Brain"},{"text":"Lungs"}]'::jsonb, 1, 'The skin is the body''s largest organ, providing protection and temperature control.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'ccdcc66f4a37e860ff37f3866003dcfc'),
  ('igcse.biology', 'human-biology', 'igcse.biology/human-biology/nutrition-digestion', 'mcq', null, 'Keeping a stable internal environment is called:', '[{"text":"Homeostasis"},{"text":"Photosynthesis"},{"text":"Digestion"},{"text":"Osmosis"}]'::jsonb, 0, 'Homeostasis maintains constant internal conditions (temperature, glucose, water).', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '40e165de5ebccae357c79cf7812268b4'),
  ('igcse.biology', 'genetics', 'igcse.biology/genetics/dna-protein', 'mcq', null, 'Which molecule carries genetic information?', '[{"text":"RNA"},{"text":"Protein"},{"text":"Lipid"},{"text":"DNA"}]'::jsonb, 3, 'DNA (deoxyribonucleic acid) carries the genetic blueprint. It''s stored in chromosomes in the cell nucleus.', 2, 'recall', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'f9f8a300ff5da3541693ff03341a1448'),
  ('igcse.biology', 'genetics', 'igcse.biology/genetics/dna-protein', 'mcq', null, 'DNA base pairing rules: Adenine pairs with:', '[{"text":"Cytosine"},{"text":"Guanine"},{"text":"Adenine"},{"text":"Thymine"}]'::jsonb, 3, 'In DNA: A pairs with T (adenine-thymine) and G pairs with C (guanine-cytosine), held by hydrogen bonds.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '1941383a97df30f99c611364975b4288'),
  ('igcse.biology', 'genetics', 'igcse.biology/genetics/monohybrid', 'mcq', null, 'A dominant allele:', '[{"text":"Is only expressed in females"},{"text":"Is always harmful"},{"text":"Is expressed even with one copy"},{"text":"Is always expressed over two copies"}]'::jsonb, 2, 'A dominant allele is expressed even in heterozygotes (one copy). Only ONE copy needed for expression.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '973171aa1797a402d3956697bb9cb52b'),
  ('igcse.biology', 'genetics', 'igcse.biology/genetics/dna-protein', 'mcq', null, 'A mutation is:', '[{"text":"Normal gene expression"},{"text":"A type of protein"},{"text":"A change in DNA sequence"},{"text":"Cell division"}]'::jsonb, 2, 'A mutation is any change in the DNA sequence. Mutations can be beneficial, neutral, or harmful.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '6b3a2df446e5f5114fc4282092a21e7c'),
  ('igcse.biology', 'genetics', 'igcse.biology/genetics/dna-protein', 'mcq', null, 'A gene is a section of:', '[{"text":"Protein"},{"text":"DNA that codes for a trait"},{"text":"Carbohydrate"},{"text":"Cell membrane"}]'::jsonb, 1, 'A gene is a length of DNA coding for a particular protein/characteristic.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'edd4e66b1ed73c27a8379e8302b45007'),
  ('igcse.biology', 'genetics', 'igcse.biology/genetics/monohybrid', 'mcq', null, 'The genotype of an organism is its:', '[{"text":"Physical appearance"},{"text":"Genetic makeup"},{"text":"Blood type only"},{"text":"Environment"}]'::jsonb, 1, 'Genotype = the alleles an organism carries; phenotype = the observable traits.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '4969038bc3741e80b43865cefd66b40a'),
  ('igcse.biology', 'genetics', 'igcse.biology/genetics/monohybrid', 'mcq', null, 'A homozygous individual has:', '[{"text":"Two different alleles"},{"text":"Two identical alleles"},{"text":"No alleles"},{"text":"One chromosome"}]'::jsonb, 1, 'Homozygous = two identical alleles (e.g. AA or aa); heterozygous = two different (Aa).', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '85b9ff10893fe33ac2bae12c2f4f217a'),
  ('igcse.biology', 'genetics', 'igcse.biology/genetics/dna-protein', 'mcq', null, 'Human body (somatic) cells contain how many chromosomes?', '[{"text":"23"},{"text":"46"},{"text":"48"},{"text":"92"}]'::jsonb, 1, 'Humans have 46 chromosomes (23 pairs) in body cells; gametes have 23.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '2fdd0d210e710ca3cdc8678dfd266726'),
  ('igcse.biology', 'genetics', 'igcse.biology/genetics/dna-protein', 'mcq', null, 'Sex in humans is determined by chromosomes:', '[{"text":"XX/XY"},{"text":"AA/BB"},{"text":"23 only"},{"text":"RR/rr"}]'::jsonb, 0, 'XX = female, XY = male. The Y chromosome carries male-determining genes.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '75ce9ecbae7f8cd0921f0e00548a1d99'),
  ('igcse.biology', 'genetics', 'igcse.biology/genetics/dna-protein', 'mcq', null, 'Variation within a species is caused by:', '[{"text":"Only environment"},{"text":"Genes and environment"},{"text":"Only chromosomes"},{"text":"Neither"}]'::jsonb, 1, 'Variation arises from genetic differences and environmental influences.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '5dbf4ec3a1194843c063da40968b08e9'),
  ('igcse.biology', 'genetics', 'igcse.biology/genetics/variation-selection', 'mcq', null, 'Natural selection favours organisms that are:', '[{"text":"Largest"},{"text":"Best adapted to survive and reproduce"},{"text":"Oldest"},{"text":"Most numerous"}]'::jsonb, 1, 'Better-adapted individuals survive and pass on their alleles (''survival of the fittest'').', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '35755aec26c6663666882944da67d680'),
  ('igcse.biology', 'genetics', 'igcse.biology/genetics/dna-protein', 'mcq', null, 'DNA is structured as a:', '[{"text":"Single strand"},{"text":"Double helix"},{"text":"Triangle"},{"text":"Sphere"}]'::jsonb, 1, 'DNA is a double helix of two complementary strands (Watson & Crick).', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '7794ffbd0d4996de11878e54399d777b'),
  ('igcse.biology', 'ecology', 'igcse.biology/ecology/food-chains', 'mcq', null, 'In a food chain, producers are:', '[{"text":"Animals"},{"text":"Decomposers"},{"text":"Fungi"},{"text":"Plants"}]'::jsonb, 3, 'Plants are producers — they make their own food via photosynthesis. All other organisms are consumers.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '05fe2a2156e7371a530b2c08ceeb4ce5'),
  ('igcse.biology', 'ecology', 'igcse.biology/ecology/photosynthesis', 'mcq', null, 'Photosynthesis equation: CO₂ + H₂O →', '[{"text":"O₂ + CO₂"},{"text":"Glucose + O₂"},{"text":"H₂O + O₂"},{"text":"Glucose + CO₂"}]'::jsonb, 1, '6CO₂ + 6H₂O + light energy → C₆H₁₂O₆ (glucose) + 6O₂. Chlorophyll absorbs light energy.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '0f2a5029043c551152e3da7df1f03456'),
  ('igcse.biology', 'ecology', 'igcse.biology/ecology/populations', 'mcq', null, 'Biodiversity refers to:', '[{"text":"Number of individuals in one species"},{"text":"Habitat size"},{"text":"Total biomass"},{"text":"Variety of species in an area"}]'::jsonb, 3, 'Biodiversity = the variety of life — species diversity, genetic diversity, and ecosystem diversity.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'de4169dd0024b6c53991f1118cc4f868'),
  ('igcse.biology', 'ecology', 'igcse.biology/ecology/food-chains', 'mcq', null, 'Decomposers in an ecosystem:', '[{"text":"Hunt prey"},{"text":"Produce oxygen"},{"text":"Break down dead organic matter"},{"text":"Graze on plants"}]'::jsonb, 2, 'Decomposers (bacteria, fungi) break down dead organisms and return nutrients to the soil — essential for nutrient cycling.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '5b761f81b6dc072c9d94988d273828a4'),
  ('igcse.biology', 'ecology', 'igcse.biology/ecology/food-chains', 'mcq', null, 'Energy enters most ecosystems from the:', '[{"text":"Soil"},{"text":"Sun"},{"text":"Wind"},{"text":"Water"}]'::jsonb, 1, 'The Sun is the primary energy source, captured by producers in photosynthesis.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'c39e99b1c3bdbed4ca2499597a850fba'),
  ('igcse.biology', 'ecology', 'igcse.biology/ecology/food-chains', 'mcq', null, 'Organisms that make their own food are:', '[{"text":"Consumers"},{"text":"Producers"},{"text":"Decomposers"},{"text":"Predators"}]'::jsonb, 1, 'Producers (plants, algae) make food via photosynthesis.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'e03f795e7b586086af301aa377edf6e5'),
  ('igcse.biology', 'ecology', 'igcse.biology/ecology/food-chains', 'mcq', null, 'A herbivore is a:', '[{"text":"Plant eater"},{"text":"Meat eater"},{"text":"Decomposer"},{"text":"Producer"}]'::jsonb, 0, 'Herbivores eat only plants; carnivores eat meat; omnivores eat both.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '6b9f3d9fba9dbd1ae3e57ee81a1381aa'),
  ('igcse.biology', 'ecology', 'igcse.biology/ecology/nutrient-cycles', 'mcq', null, 'The carbon cycle returns CO₂ to the air mainly through:', '[{"text":"Photosynthesis"},{"text":"Respiration and combustion"},{"text":"Osmosis"},{"text":"Filtration"}]'::jsonb, 1, 'Respiration and burning fuels release CO₂; photosynthesis removes it.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '2036c0ab5be5ceabe3768fd8cb31c605'),
  ('igcse.biology', 'ecology', 'igcse.biology/ecology/food-chains', 'mcq', null, 'A population is:', '[{"text":"All organisms of one species in an area"},{"text":"All living things on Earth"},{"text":"Only predators"},{"text":"A single organism"}]'::jsonb, 0, 'A population is all members of one species in a particular area.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'fcda13725054c2c3dc53cedecc16bf48'),
  ('igcse.biology', 'ecology', 'igcse.biology/ecology/food-chains', 'mcq', null, 'Decomposers are important because they:', '[{"text":"Produce oxygen"},{"text":"Recycle nutrients from dead matter"},{"text":"Hunt prey"},{"text":"Make sunlight"}]'::jsonb, 1, 'Decomposers break down dead organisms, returning nutrients to the soil.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '935bc2f73efc658aa80565b94c59ea8b'),
  ('igcse.biology', 'ecology', 'igcse.biology/ecology/human-impact', 'mcq', null, 'Burning fossil fuels increases atmospheric:', '[{"text":"Oxygen"},{"text":"Carbon dioxide"},{"text":"Nitrogen"},{"text":"Helium"}]'::jsonb, 1, 'Combustion of fossil fuels releases CO₂, a greenhouse gas.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'd5ec0adb18cd3f9f08d88b1e09e5cb9a'),
  ('igcse.biology', 'ecology', 'igcse.biology/ecology/populations', 'mcq', null, 'Biodiversity is a measure of:', '[{"text":"Total mass of one species"},{"text":"The variety of living organisms"},{"text":"Land area"},{"text":"Water volume"}]'::jsonb, 1, 'Biodiversity is the range of different species in an ecosystem.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'fb28fedd44cb13116b7a09f03481aca6'),
  ('igcse.chemistry', 'physical', 'igcse.chemistry/physical/rates', 'mcq', null, 'Rate of reaction increases with temperature because:', '[{"text":"More particles exist"},{"text":"Activation energy increases"},{"text":"More collisions with sufficient energy occur"},{"text":"Concentration decreases"}]'::jsonb, 2, 'Higher temperature means more particles have energy ≥ activation energy, so more successful collisions per second.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'ae4f93c2d859b53e1d4754d90da232d3'),
  ('igcse.chemistry', 'physical', 'igcse.chemistry/physical/equilibrium', 'mcq', null, 'At dynamic equilibrium:', '[{"text":"Reaction has stopped"},{"text":"Forward and reverse rates are equal"},{"text":"Only products remain"},{"text":"Concentration reaches zero"}]'::jsonb, 1, 'At equilibrium, both forward and reverse reactions continue at equal rates — concentrations remain constant but not zero.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '66e0000cc32dc6cfb587a773f815fc80'),
  ('igcse.chemistry', 'inorganic', 'igcse.chemistry/inorganic/acids-salts', 'mcq', null, 'pH 7 indicates a solution is:', '[{"text":"Acidic"},{"text":"Strongly basic"},{"text":"Neutral"},{"text":"Weakly acidic"}]'::jsonb, 2, 'pH 7 is neutral (like pure water). pH < 7 = acidic, pH > 7 = basic/alkaline.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '9be7300f29c11910da4cedee04c5b2ba'),
  ('igcse.chemistry', 'physical', 'igcse.chemistry/physical/equilibrium', 'mcq', null, 'A catalyst:', '[{"text":"Is consumed in the reaction"},{"text":"Raises activation energy"},{"text":"Lowers activation energy without being consumed"},{"text":"Changes the equilibrium position"}]'::jsonb, 2, 'Catalysts lower activation energy, speeding up the reaction without being permanently consumed. They don''t shift equilibrium.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'caa057737a35fc52429dd6aeb013431b'),
  ('igcse.chemistry', 'physical', 'igcse.chemistry/physical/rates', 'mcq', null, 'Increasing concentration of reactants generally:', '[{"text":"Slows the reaction"},{"text":"Speeds the reaction"},{"text":"Stops it"},{"text":"No effect"}]'::jsonb, 1, 'More concentrated reactants → more frequent collisions → faster rate.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'deab6565ad42ce8d9a589ae8a5ec54ce'),
  ('igcse.chemistry', 'physical', 'igcse.chemistry/physical/energetics', 'mcq', null, 'A reaction that releases heat is:', '[{"text":"Endothermic"},{"text":"Exothermic"},{"text":"Neutral"},{"text":"Catalytic"}]'::jsonb, 1, 'Exothermic reactions release heat (ΔH negative); endothermic absorb it.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'de716552907185b0ea05a96ab12fdd4f'),
  ('igcse.chemistry', 'physical', 'igcse.chemistry/physical/energetics', 'mcq', null, 'Activation energy is the:', '[{"text":"Energy released by a reaction"},{"text":"Minimum energy needed to react"},{"text":"Energy of products"},{"text":"Heat of the room"}]'::jsonb, 1, 'Activation energy is the minimum energy colliding particles need to react.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '94eadc3954c00559e3e5861dfb4c008d'),
  ('igcse.chemistry', 'physical', 'igcse.chemistry/physical/rates', 'mcq', null, 'Raising temperature increases reaction rate mainly because particles:', '[{"text":"Get bigger"},{"text":"Move faster and collide more energetically"},{"text":"Lose charge"},{"text":"Stop moving"}]'::jsonb, 1, 'Higher temperature → faster particles → more frequent, more energetic collisions.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '1906a0413f04a00d5c6cff209e7b7c80'),
  ('igcse.chemistry', 'inorganic', 'igcse.chemistry/inorganic/acids-salts', 'mcq', null, 'The pH of a strong acid is typically:', '[{"text":"Around 7"},{"text":"Below 3"},{"text":"Above 11"},{"text":"Exactly 14"}]'::jsonb, 1, 'Strong acids have low pH (often 0–2). pH 7 is neutral.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '649ecf6ba6b95dd188580d214f053abb'),
  ('igcse.chemistry', 'physical', 'igcse.chemistry/physical/rates', 'mcq', null, 'A catalyst changes the rate by providing a:', '[{"text":"Higher energy path"},{"text":"Lower activation-energy path"},{"text":"New product"},{"text":"Source of heat"}]'::jsonb, 1, 'Catalysts offer an alternative route with lower activation energy and are not consumed.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '74c8693e33c99430ab8ef8026c4e636d'),
  ('igcse.chemistry', 'physical', 'igcse.chemistry/physical/energetics', 'mcq', null, 'Endothermic reactions cause the surroundings to:', '[{"text":"Heat up"},{"text":"Cool down"},{"text":"Stay the same"},{"text":"Catch fire"}]'::jsonb, 1, 'Endothermic reactions absorb heat from the surroundings, cooling them.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '5a12c1c708110737e326085e22759a54'),
  ('igcse.chemistry', 'inorganic', 'igcse.chemistry/inorganic/periodic-table', 'mcq', null, 'Which Group 1 metal is the most reactive?', '[{"text":"Lithium"},{"text":"Sodium"},{"text":"Potassium"},{"text":"Caesium"}]'::jsonb, 3, 'Reactivity increases DOWN Group 1. Caesium (Cs) is the most reactive, as its outer electron is furthest from the nucleus.', 3, 'recall', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'ddbbe4182b7f2665674a13e91a4e9814'),
  ('igcse.chemistry', 'inorganic', 'igcse.chemistry/inorganic/bonding', 'mcq', null, 'Transition metals typically form:', '[{"text":"Only white/colourless compounds"},{"text":"Coloured compounds"},{"text":"Only ionic bonds"},{"text":"No complex ions"}]'::jsonb, 1, 'Transition metals form coloured compounds due to partially filled d-orbitals. They also form complex ions and have variable oxidation states.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '5f1bed2b279cfd01cc0e1e1051a2516b'),
  ('igcse.chemistry', 'inorganic', 'igcse.chemistry/inorganic/acids-salts', 'mcq', null, 'Acid + Metal Carbonate produces:', '[{"text":"Salt + Water only"},{"text":"Salt + Water + CO₂"},{"text":"Salt + H₂"},{"text":"Just CO₂"}]'::jsonb, 1, 'Acid + Metal Carbonate → Salt + Water + Carbon Dioxide. E.g., HCl + CaCO₃ → CaCl₂ + H₂O + CO₂', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '7f57e7fdb869d1de7c44cee052f63652'),
  ('igcse.chemistry', 'physical', 'igcse.chemistry/physical/electrolysis', 'mcq', null, 'Electrolysis requires:', '[{"text":"AC current"},{"text":"No current"},{"text":"DC current"},{"text":"Heat only"}]'::jsonb, 2, 'DC (Direct Current) is required for electrolysis so that positive ions consistently move to the cathode and negative to anode.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'fc6ed85df65d0babd7efa91e5f96abaf'),
  ('igcse.chemistry', 'inorganic', 'igcse.chemistry/inorganic/periodic-table', 'mcq', null, 'Group 7 elements are called the:', '[{"text":"Alkali metals"},{"text":"Halogens"},{"text":"Noble gases"},{"text":"Transition metals"}]'::jsonb, 1, 'Group 7 (F, Cl, Br, I) are the halogens — reactive non-metals.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '4fe3ca7a1c425cff2d397015af451ff1'),
  ('igcse.chemistry', 'inorganic', 'igcse.chemistry/inorganic/atomic-structure', 'mcq', null, 'Noble gases are unreactive because they have:', '[{"text":"No electrons"},{"text":"A full outer shell"},{"text":"Extra protons"},{"text":"No nucleus"}]'::jsonb, 1, 'A full outer electron shell makes noble gases stable and unreactive.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '75d5043295ce9f1532c0b98f7b62b182'),
  ('igcse.chemistry', 'inorganic', 'igcse.chemistry/inorganic/acids-salts', 'mcq', null, 'An acid reacting with a base produces a salt and:', '[{"text":"Hydrogen"},{"text":"Water"},{"text":"Oxygen"},{"text":"CO₂"}]'::jsonb, 1, 'Neutralisation: acid + base → salt + water.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'abb7242b01b13590613f2fe8e02ca260'),
  ('igcse.chemistry', 'inorganic', 'igcse.chemistry/inorganic/acids-salts', 'mcq', null, 'Acid + reactive metal typically produces a salt and:', '[{"text":"Water"},{"text":"Hydrogen gas"},{"text":"Oxygen"},{"text":"CO₂"}]'::jsonb, 1, 'Acid + metal → salt + hydrogen (test: squeaky pop).', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '03f88b736b9bd4f27d70e74f7b196821'),
  ('igcse.chemistry', 'physical', 'igcse.chemistry/physical/electrolysis', 'mcq', null, 'During electrolysis, positive ions move to the:', '[{"text":"Anode"},{"text":"Cathode"},{"text":"Electrolyte"},{"text":"Wire"}]'::jsonb, 1, 'Cations (positive) are attracted to the cathode (negative electrode).', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'c4e2e24817469deebb3c6a8a4c2b304b'),
  ('igcse.chemistry', 'inorganic', 'igcse.chemistry/inorganic/metals-reactivity', 'mcq', null, 'A more reactive metal can displace a less reactive metal from its:', '[{"text":"Atom"},{"text":"Salt solution"},{"text":"Nucleus"},{"text":"Gas"}]'::jsonb, 1, 'Displacement: a more reactive metal takes the place of a less reactive one in a compound.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'a7bce57d86b1440c75479fa3a0271734'),
  ('igcse.chemistry', 'inorganic', 'igcse.chemistry/inorganic/metals-reactivity', 'mcq', null, 'Rusting of iron requires:', '[{"text":"Only heat"},{"text":"Oxygen and water"},{"text":"Nitrogen only"},{"text":"No conditions"}]'::jsonb, 1, 'Iron rusts when exposed to both oxygen and water (hydrated iron(III) oxide).', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'a141c2bbd3b3787825a380080f10960c'),
  ('igcse.chemistry', 'organic', 'igcse.chemistry/organic/functional-groups', 'mcq', null, 'What is the functional group of alcohols?', '[{"text":"-COOH"},{"text":"-CHO"},{"text":"-OH"},{"text":"-NH₂"}]'::jsonb, 2, '-OH (hydroxyl group) is the functional group of alcohols. It makes compounds soluble in water.', 2, 'recall', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '6e9c7efc0cfe5d9c0fd123e78f722644'),
  ('igcse.chemistry', 'organic', 'igcse.chemistry/organic/hydrocarbons', 'mcq', null, 'Which of the following is an alkane?', '[{"text":"Ethene"},{"text":"Ethyne"},{"text":"Ethanol"},{"text":"Ethane"}]'::jsonb, 3, 'Ethane (C₂H₆) is an alkane — single bonds only. Ethene has a double bond (alkene), ethyne a triple bond (alkyne).', 2, 'recall', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '8d6781da40bb01e360181defdd37303b'),
  ('igcse.chemistry', 'organic', 'igcse.chemistry/organic/functional-groups', 'mcq', null, 'Esterification is the reaction between:', '[{"text":"Acid + Base"},{"text":"Alcohol + Carboxylic Acid"},{"text":"Alkene + Hydrogen"},{"text":"Aldehyde + Alcohol"}]'::jsonb, 1, 'Ester = Alcohol + Carboxylic Acid → Ester + Water. This condensation reaction is reversible.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '4c7f3c481329d94f191fd5ea94e640f8'),
  ('igcse.chemistry', 'organic', 'igcse.chemistry/organic/functional-groups', 'mcq', null, 'Ethanol formula:', '[{"text":"C₂H₄"},{"text":"C₂H₄O₂"},{"text":"CH₃COOH"},{"text":"C₂H₅OH"}]'::jsonb, 3, 'Ethanol = C₂H₅OH (or C₂H₆O). It''s the alcohol in beverages.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '0cc9237ff0d70b4be60756f6188866e7'),
  ('igcse.chemistry', 'organic', 'igcse.chemistry/organic/hydrocarbons', 'mcq', null, 'The general formula of alkanes is:', '[{"text":"CnH2n"},{"text":"CnH2n+2"},{"text":"CnH2n-2"},{"text":"CnHn"}]'::jsonb, 1, 'Alkanes are saturated: CnH2n+2 (e.g. methane CH₄, ethane C₂H₆).', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '590e6354782785488be0e81ff8ec7a71'),
  ('igcse.chemistry', 'organic', 'igcse.chemistry/organic/hydrocarbons', 'mcq', null, 'Which is unsaturated?', '[{"text":"Ethane"},{"text":"Propane"},{"text":"Ethene"},{"text":"Butane"}]'::jsonb, 2, 'Ethene (C₂H₄) has a C=C double bond, making it unsaturated.', 2, 'recall', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'd43d64a8cd91d568832c0a01b042c2bc'),
  ('igcse.chemistry', 'organic', 'igcse.chemistry/organic/hydrocarbons', 'mcq', null, 'Complete combustion of a hydrocarbon produces:', '[{"text":"CO + H₂O"},{"text":"CO₂ + H₂O"},{"text":"C + H₂"},{"text":"CO₂ + H₂"}]'::jsonb, 1, 'Complete combustion gives carbon dioxide and water. Incomplete gives CO or soot.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '0ea1cf5cf8102743db677331f73b16e6'),
  ('igcse.chemistry', 'organic', 'igcse.chemistry/organic/functional-groups', 'mcq', null, 'The functional group of carboxylic acids is:', '[{"text":"-OH"},{"text":"-CHO"},{"text":"-COOH"},{"text":"-CO-"}]'::jsonb, 2, 'Carboxylic acids contain -COOH (e.g. ethanoic acid, CH₃COOH).', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'f194a6cf9eff8e9591383462cca2db78'),
  ('igcse.chemistry', 'organic', 'igcse.chemistry/organic/polymers', 'mcq', null, 'Polymers are made from many:', '[{"text":"Atoms"},{"text":"Monomers"},{"text":"Isotopes"},{"text":"Ions"}]'::jsonb, 1, 'Polymers form when many small monomer molecules join into long chains.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'ba71e1148fcaed48b5fbe8d491c2bb55'),
  ('igcse.chemistry', 'organic', 'igcse.chemistry/organic/hydrocarbons', 'mcq', null, 'Which homologous series contains a C=C bond?', '[{"text":"Alkanes"},{"text":"Alkenes"},{"text":"Alcohols"},{"text":"Carboxylic acids"}]'::jsonb, 1, 'Alkenes contain at least one carbon–carbon double bond.', 2, 'recall', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '144fc9cd37365a5bf11da71e9351fcd8'),
  ('igcse.chemistry', 'organic', 'igcse.chemistry/organic/functional-groups', 'mcq', null, 'Fermentation of glucose produces ethanol and:', '[{"text":"Oxygen"},{"text":"Carbon dioxide"},{"text":"Hydrogen"},{"text":"Methane"}]'::jsonb, 1, 'Yeast ferments glucose into ethanol and CO₂ anaerobically.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'd2c4ab38cbbde6f171534c6d77983261'),
  ('igcse.chemistry', 'analysis', 'igcse.chemistry/analysis/ion-tests', 'mcq', null, 'Flame test for sodium gives which colour?', '[{"text":"Crimson red"},{"text":"Lilac/violet"},{"text":"Bright yellow"},{"text":"Apple green"}]'::jsonb, 2, 'Sodium gives a distinctive bright yellow/orange-yellow flame. It''s so intense it can mask other metals.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'c3238bcf1bee371983b8a1a11ffa59ea'),
  ('igcse.chemistry', 'analysis', 'igcse.chemistry/analysis/ion-tests', 'mcq', null, 'Which reagent is used to test for starch?', '[{"text":"Benedict''s solution"},{"text":"Biuret reagent"},{"text":"Iodine solution"},{"text":"Fehling''s solution"}]'::jsonb, 2, 'Iodine solution turns blue-black in the presence of starch — one of the most recognisable tests in chemistry.', 2, 'recall', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'fdcbcff90a9d8f8456baee13c50c4ae0'),
  ('igcse.chemistry', 'analysis', 'igcse.chemistry/analysis/ion-tests', 'mcq', null, 'A lit splint gives a ''squeaky pop'' with which gas?', '[{"text":"Oxygen"},{"text":"Hydrogen"},{"text":"Carbon dioxide"},{"text":"Chlorine"}]'::jsonb, 1, 'Hydrogen burns with a squeaky pop when a lit splint is introduced.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '3929643b282df9d867f9f0054746732b'),
  ('igcse.chemistry', 'analysis', 'igcse.chemistry/analysis/ion-tests', 'mcq', null, 'Limewater turns milky/cloudy in the presence of:', '[{"text":"Oxygen"},{"text":"Carbon dioxide"},{"text":"Hydrogen"},{"text":"Nitrogen"}]'::jsonb, 1, 'CO₂ turns limewater (calcium hydroxide solution) cloudy.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'da474a993c4a73814c24f98623c27d8f'),
  ('igcse.chemistry', 'analysis', 'igcse.chemistry/analysis/ion-tests', 'mcq', null, 'A glowing splint relights in:', '[{"text":"Hydrogen"},{"text":"Oxygen"},{"text":"CO₂"},{"text":"Chlorine"}]'::jsonb, 1, 'Oxygen relights a glowing splint because it supports combustion.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'ab9a0109958ffbe31bbab000679f2bf1'),
  ('igcse.chemistry', 'analysis', 'igcse.chemistry/analysis/ion-tests', 'mcq', null, 'A potassium flame test gives which colour?', '[{"text":"Yellow"},{"text":"Lilac"},{"text":"Green"},{"text":"Red"}]'::jsonb, 1, 'Potassium produces a lilac/purple flame.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'c761d630c95a290fcd484ee8187e76a2'),
  ('igcse.physics', 'motion-forces-energy', 'igcse.physics/motion-forces-energy/forces', 'mcq', null, 'Newton''s Second Law states:', '[{"text":"Every action has equal and opposite reaction"},{"text":"F = ma"},{"text":"Objects in motion stay in motion"},{"text":"F = mv"}]'::jsonb, 1, 'F = ma: Net force equals mass times acceleration. The more force, the more acceleration; the more mass, the less acceleration.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '6103c9e0421029c81e1596f9af892848'),
  ('igcse.physics', 'motion-forces-energy', 'igcse.physics/motion-forces-energy/forces', 'mcq', null, 'A 1000 kg car accelerates at 3 m/s². What force is applied?', '[{"text":"333 N"},{"text":"1003 N"},{"text":"300 N"},{"text":"3000 N"}]'::jsonb, 3, 'F = ma = 1000 × 3 = 3000 N', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '0248136e1ad716afb5fbc107ef46bd1e'),
  ('igcse.physics', 'motion-forces-energy', 'igcse.physics/motion-forces-energy/motion', 'mcq', null, 'Formula for kinetic energy is:', '[{"text":"KE = mv"},{"text":"KE = mv²"},{"text":"KE = ½mv²"},{"text":"KE = 2mv²"}]'::jsonb, 2, 'Kinetic energy = ½mv². It increases with the square of velocity — doubling speed quadruples KE.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '03eb726c8647ef9e6fe3cef57d057ccf'),
  ('igcse.physics', 'motion-forces-energy', 'igcse.physics/motion-forces-energy/motion', 'mcq', null, 'What is the free-fall acceleration on Earth (approx.)?', '[{"text":"5 m/s²"},{"text":"9.8 m/s²"},{"text":"10.2 m/s²"},{"text":"15 m/s²"}]'::jsonb, 1, 'Gravitational acceleration g ≈ 9.8 m/s² (often rounded to 10 m/s² in calculations).', 2, 'recall', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'e14e158ce9e27bd46c5cb6cff169be95'),
  ('igcse.physics', 'motion-forces-energy', 'igcse.physics/motion-forces-energy/energy-work-power', 'mcq', null, 'Work = Force × Distance. F=20N, d=5m. Work done = ?', '[{"text":"4 J"},{"text":"25 J"},{"text":"100 J"},{"text":"20 J"}]'::jsonb, 2, 'W = F × d = 20 × 5 = 100 J (Joules)', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '32ada32e336d35080c9aad0322da9136'),
  ('igcse.physics', 'motion-forces-energy', 'igcse.physics/motion-forces-energy/motion', 'mcq', null, 'Momentum (p) formula:', '[{"text":"p = ma"},{"text":"p = mv"},{"text":"p = m/v"},{"text":"p = Ft"}]'::jsonb, 1, 'Momentum = mass × velocity = mv. It''s a vector quantity (has direction).', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '7d25a39c0e417df2ac167413c17ec79b'),
  ('igcse.physics', 'thermal', 'igcse.physics/thermal/gas-behaviour', 'mcq', null, 'What is the SI unit of temperature?', '[{"text":"Celsius"},{"text":"Kelvin"},{"text":"Fahrenheit"},{"text":"Rankine"}]'::jsonb, 1, 'The SI unit is Kelvin (K). Absolute zero is 0 K = −273.15°C.', 2, 'recall', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '6e7b65a840b87eb2054f143b637dcf63'),
  ('igcse.physics', 'thermal', 'igcse.physics/thermal/particle-model', 'mcq', null, 'The first law of thermodynamics states that:', '[{"text":"Entropy always increases"},{"text":"Energy cannot be created or destroyed"},{"text":"Heat flows from cold to hot"},{"text":"All systems tend to disorder"}]'::jsonb, 1, 'The first law is conservation of energy: ΔU = Q − W. Energy is neither created nor destroyed.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'c9ddf6615d219c38cf7514a0c1a1e505'),
  ('igcse.physics', 'thermal', 'igcse.physics/thermal/gas-behaviour', 'mcq', null, 'Absolute zero in Celsius is:', '[{"text":"0°C"},{"text":"-100°C"},{"text":"-273°C"},{"text":"-373°C"}]'::jsonb, 2, 'Absolute zero = 0 K = −273.15°C. At this temperature, all molecular motion theoretically stops.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '65d8c2850bf5d6c501c9e4433978703e'),
  ('igcse.physics', 'thermal', 'igcse.physics/thermal/gas-behaviour', 'mcq', null, 'An ideal gas is compressed at constant temperature. Its pressure:', '[{"text":"Decreases"},{"text":"Stays same"},{"text":"Increases"},{"text":"Becomes zero"}]'::jsonb, 2, 'Boyle''s Law: PV = constant (at fixed T). If V decreases, P must increase.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '34a97ead87df1cc9ae7170a724d586f1'),
  ('igcse.physics', 'thermal', 'igcse.physics/thermal/thermal-energy', 'mcq', null, 'Specific heat capacity of water is approximately:', '[{"text":"1 J/g·K"},{"text":"2.09 J/g·K"},{"text":"4.18 J/g·K"},{"text":"8.36 J/g·K"}]'::jsonb, 2, 'Water has a specific heat of ~4.18 J/g·K — the highest of common substances, making it excellent for storing heat.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '7761f7a84914e7b25af043aa1ba2b04a'),
  ('igcse.physics', 'thermal', 'igcse.physics/thermal/heat-transfer', 'mcq', null, 'Which process involves heat transfer without a medium (e.g., through space)?', '[{"text":"Conduction"},{"text":"Convection"},{"text":"Radiation"},{"text":"Advection"}]'::jsonb, 2, 'Radiation transfers heat via electromagnetic waves and requires no medium — that''s how the Sun heats Earth.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'c6872ffe6f2740f405fc3c5f1d9a1a51'),
  ('igcse.physics', 'waves', 'igcse.physics/waves/wave-properties', 'mcq', null, 'A wave has a frequency of 50 Hz and a wavelength of 4 m. What is the speed of the wave?', '[{"text":"200 m/s"},{"text":"100 m/s"},{"text":"25 m/s"},{"text":"12.5 m/s"}]'::jsonb, 0, 'Speed = Frequency × Wavelength = 50 × 4 = 200 m/s. Always use v = fλ.', 3, 'apply', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '9a4d4a22293f2754700e8cb93258cfe1'),
  ('igcse.physics', 'waves', 'igcse.physics/waves/wave-properties', 'mcq', null, 'The period of a wave is 0.02 seconds. What is its frequency?', '[{"text":"20 Hz"},{"text":"50 Hz"},{"text":"0.02 Hz"},{"text":"5 Hz"}]'::jsonb, 1, 'Frequency = 1 / Period = 1 / 0.02 = 50 Hz. These are inversely related.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '7333c039910564e18636f1a57653815b'),
  ('igcse.physics', 'waves', 'igcse.physics/waves/sound', 'mcq', null, 'Which of the following is an example of a transverse wave?', '[{"text":"Sound in air"},{"text":"Compression spring wave"},{"text":"Light wave"},{"text":"Seismic P-wave"}]'::jsonb, 2, 'Light is a transverse wave — the oscillation is perpendicular to the direction of travel.', 2, 'recall', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '627600dd5f5f7b3ee0a18be40d586d4c'),
  ('igcse.physics', 'waves', 'igcse.physics/waves/sound', 'mcq', null, 'Sound travels fastest through which medium?', '[{"text":"Air"},{"text":"Water"},{"text":"Vacuum"},{"text":"Steel"}]'::jsonb, 3, 'Sound travels fastest through solids like steel (~5000 m/s) because particles are close together.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '339173b2717fc31dc6d9f2d52cb4dfbf'),
  ('igcse.physics', 'waves', 'igcse.physics/waves/wave-properties', 'mcq', null, 'A wavelength of 0.5 m and speed 340 m/s. What is the frequency?', '[{"text":"170 Hz"},{"text":"680 Hz"},{"text":"340 Hz"},{"text":"85 Hz"}]'::jsonb, 1, 'f = v/λ = 340 / 0.5 = 680 Hz', 3, 'apply', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'eb1f4ab1746e2359852441f6d76dc2d6'),
  ('igcse.physics', 'waves', 'igcse.physics/waves/wave-properties', 'mcq', null, 'What happens to frequency when a sound source moves toward you (Doppler Effect)?', '[{"text":"Decreases"},{"text":"Stays the same"},{"text":"Increases"},{"text":"Becomes zero"}]'::jsonb, 2, 'As the source moves toward you, wavefronts compress, increasing the perceived frequency (higher pitch).', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '57b471d71996b9f6af19b4a739bb61a4'),
  ('igcse.physics', 'electricity', 'igcse.physics/electricity/resistance', 'mcq', null, 'Ohm''s Law is expressed as:', '[{"text":"V = IR"},{"text":"V = I/R"},{"text":"I = VR"},{"text":"R = VI"}]'::jsonb, 0, 'Ohm''s Law: V = IR (Voltage = Current × Resistance). This is fundamental to circuit analysis.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '78d098c6159a279ee28e489b2703319b'),
  ('igcse.physics', 'electricity', 'igcse.physics/electricity/power-energy', 'mcq', null, 'Electric power formula is:', '[{"text":"P = IV"},{"text":"P = I/V"},{"text":"P = V/I"},{"text":"P = I + V"}]'::jsonb, 0, 'P = IV = I²R = V²/R. All three are equivalent using Ohm''s Law.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'b0d6bb476dc81c0d41838a065cc3bd8d'),
  ('igcse.physics', 'electricity', 'igcse.physics/electricity/charge-current', 'mcq', null, 'V = 12V, R = 4Ω. What is the current?', '[{"text":"48A"},{"text":"0.33A"},{"text":"3A"},{"text":"8A"}]'::jsonb, 2, 'I = V/R = 12 / 4 = 3A (Ohm''s Law rearranged).', 3, 'apply', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'ec30b2993ba43f4af1660d45a41d0b6a'),
  ('igcse.physics', 'electricity', 'igcse.physics/electricity/resistance', 'mcq', null, 'Three 6Ω resistors are connected in series. Total resistance is:', '[{"text":"2Ω"},{"text":"18Ω"},{"text":"6Ω"},{"text":"12Ω"}]'::jsonb, 1, 'In series: R_total = R₁ + R₂ + R₃ = 6 + 6 + 6 = 18Ω.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '4e16eda8ba8ab7494b38514bb8bf72f2'),
  ('igcse.physics', 'electricity', 'igcse.physics/electricity/power-energy', 'mcq', null, 'A kilowatt-hour (kWh) measures:', '[{"text":"Power"},{"text":"Current"},{"text":"Energy"},{"text":"Voltage"}]'::jsonb, 2, 'kWh is a unit of energy = Power × Time. 1 kWh = 3,600,000 joules.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '778f85cc18280d90ab31ad768d1aa433'),
  ('igcse.physics', 'magnetism', 'igcse.physics/magnetism/induction', 'mcq', null, 'The SI unit of magnetic flux density is:', '[{"text":"Weber"},{"text":"Henry"},{"text":"Tesla"},{"text":"Faraday"}]'::jsonb, 2, 'Tesla (T) is the SI unit of magnetic flux density (field strength). 1 T = 1 V·s/m².', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '8d99d8f7d680e5ff0a25842723eb62a7'),
  ('igcse.physics', 'magnetism', 'igcse.physics/magnetism/magnetic-fields', 'mcq', null, 'Like magnetic poles:', '[{"text":"Attract each other"},{"text":"Repel each other"},{"text":"Have no effect"},{"text":"Cancel out"}]'::jsonb, 1, 'Like poles repel, opposite poles attract — similar to electric charges.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '2b1e546eecde8694787c7858f8b817d8'),
  ('igcse.physics', 'magnetism', 'igcse.physics/magnetism/electromagnetism', 'mcq', null, 'Which rule gives the direction of force on a current-carrying conductor in a magnetic field?', '[{"text":"Right-hand rule"},{"text":"Fleming''s Left-Hand Rule"},{"text":"Corkscrew rule"},{"text":"Lenz''s Law"}]'::jsonb, 1, 'Fleming''s Left-Hand Rule: thumb=force (motion), index=field, middle=current direction.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '518247b7dcf034addfd52a750c451d3e'),
  ('igcse.physics', 'magnetism', 'igcse.physics/magnetism/induction', 'mcq', null, 'An electric motor converts:', '[{"text":"Mechanical to electrical energy"},{"text":"Electrical to mechanical energy"},{"text":"Chemical to electrical energy"},{"text":"Heat to mechanical energy"}]'::jsonb, 1, 'Motors convert electrical energy to mechanical energy (motion). Generators do the reverse.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '443c596d7e06c8c2540cb97689d20f8a'),
  ('igcse.physics', 'magnetism', 'igcse.physics/magnetism/magnetic-fields', 'mcq', null, 'The SI unit of magnetic flux density is the:', '[{"text":"Weber"},{"text":"Tesla"},{"text":"Henry"},{"text":"Gauss"}]'::jsonb, 1, 'Magnetic flux density (B) is measured in tesla (T). The weber is the unit of flux.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '49ad24bbab84772486047f37a78f1402'),
  ('igcse.physics', 'magnetism', 'igcse.physics/magnetism/magnetic-fields', 'mcq', null, 'Like magnetic poles:', '[{"text":"Attract"},{"text":"Repel"},{"text":"Have no force"},{"text":"Cancel charge"}]'::jsonb, 1, 'Like poles (N–N or S–S) repel; unlike poles attract.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'a67142341ae56db758d9803b14c5fd03'),
  ('igcse.physics', 'magnetism', 'igcse.physics/magnetism/electromagnetism', 'mcq', null, 'Which rule gives the direction of force on a current-carrying conductor in a magnetic field?', '[{"text":"Right-hand grip rule"},{"text":"Fleming''s left-hand rule"},{"text":"Lenz''s law"},{"text":"Fleming''s right-hand rule"}]'::jsonb, 1, 'Fleming''s left-hand rule: thumb=force, first finger=field, second finger=current.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '25bd1d6f7409d26f8708eebd8b33c097'),
  ('igcse.physics', 'magnetism', 'igcse.physics/magnetism/electromagnetism', 'mcq', null, 'An electric motor converts:', '[{"text":"Electrical to kinetic energy"},{"text":"Kinetic to electrical energy"},{"text":"Heat to light"},{"text":"Chemical to electrical"}]'::jsonb, 0, 'A motor turns electrical energy into rotational kinetic energy via the motor effect.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '55a3fe45e20b841a0087a5c29554553f'),
  ('igcse.physics', 'magnetism', 'igcse.physics/magnetism/magnetic-fields', 'mcq', null, 'The Earth behaves like a giant:', '[{"text":"Capacitor"},{"text":"Bar magnet"},{"text":"Resistor"},{"text":"Battery"}]'::jsonb, 1, 'Earth''s magnetic field resembles that of a bar magnet, with poles near the geographic poles.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '1f2709c63835aff6abc49c396978ec2f'),
  ('igcse.physics', 'nuclear-space', 'igcse.physics/nuclear-space/atomic-model', 'mcq', null, 'The photoelectric effect was explained by:', '[{"text":"Newton"},{"text":"Bohr"},{"text":"Einstein"},{"text":"Rutherford"}]'::jsonb, 2, 'Einstein explained the photoelectric effect using the concept of photons (light quanta), earning him the Nobel Prize.', 3, 'analyse', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'ff2d557c2647b9eed8f45a6892b8acef'),
  ('igcse.physics', 'nuclear-space', null, 'mcq', null, 'E = hf, where h is:', '[{"text":"Gas constant"},{"text":"Hubble constant"},{"text":"Planck''s constant"},{"text":"Boltzmann constant"}]'::jsonb, 2, 'h = Planck''s constant ≈ 6.63 × 10⁻³⁴ J·s. Used to calculate photon energy.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'pending_review', 'Imported from the original Chapter app. No skill match: check topic and syllabus fit before publishing.', '2bc4e816b16c4fedb65dbdc59e85ea8a'),
  ('igcse.physics', 'nuclear-space', 'igcse.physics/nuclear-space/radiation-safety', 'mcq', null, 'Alpha particles are:', '[{"text":"Electrons"},{"text":"Protons"},{"text":"Helium nuclei"},{"text":"Positrons"}]'::jsonb, 2, 'Alpha particles consist of 2 protons + 2 neutrons (same as a helium-4 nucleus). They are highly ionising but have low penetration.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '164855932ddf76de98f10d282b3c597a'),
  ('igcse.physics', 'nuclear-space', null, 'mcq', null, 'The mass-energy equivalence formula is:', '[{"text":"E = mc"},{"text":"E = mc²"},{"text":"E = m²c"},{"text":"E = mv²"}]'::jsonb, 1, 'Einstein''s famous E = mc² shows that mass and energy are interchangeable. c = 3×10⁸ m/s.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'pending_review', 'Imported from the original Chapter app. No skill match: check topic and syllabus fit before publishing.', '59e62585b903563c93542c4796de18ba'),
  ('igcse.physics', 'nuclear-space', 'igcse.physics/nuclear-space/atomic-model', 'mcq', null, 'Alpha particles are:', '[{"text":"Electrons"},{"text":"Helium nuclei"},{"text":"Photons"},{"text":"Neutrons"}]'::jsonb, 1, 'An alpha particle is a helium nucleus: 2 protons + 2 neutrons.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '4cbfc7a0814cf5ba27f78fcde1813208'),
  ('igcse.physics', 'nuclear-space', null, 'mcq', null, 'The mass–energy equivalence formula is:', '[{"text":"E = mc²"},{"text":"E = mgh"},{"text":"E = ½mv²"},{"text":"E = Fd"}]'::jsonb, 0, 'Einstein''s E = mc² relates mass and energy, with c the speed of light.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'pending_review', 'Imported from the original Chapter app. No skill match: check topic and syllabus fit before publishing.', '3551e61e38abc85bd3ed3f53d97de818'),
  ('igcse.physics', 'nuclear-space', 'igcse.physics/nuclear-space/radiation-safety', 'mcq', null, 'Which radiation is most penetrating?', '[{"text":"Alpha"},{"text":"Beta"},{"text":"Gamma"},{"text":"All equal"}]'::jsonb, 2, 'Gamma is most penetrating (stopped by thick lead); alpha is least (stopped by paper).', 3, 'recall', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'cd143ebd8ad429c483e85887f34ce06b'),
  ('igcse.physics', 'nuclear-space', 'igcse.physics/nuclear-space/atomic-model', 'mcq', null, 'Isotopes of an element have the same:', '[{"text":"Number of neutrons"},{"text":"Number of protons"},{"text":"Mass number"},{"text":"Number of nucleons"}]'::jsonb, 1, 'Isotopes share proton number (same element) but differ in neutron number.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '08a23a884160bd0feb3967fdcbeae869'),
  ('igcse.physics', 'nuclear-space', 'igcse.physics/nuclear-space/space', 'mcq', null, 'Nuclear fusion in the Sun mainly fuses:', '[{"text":"Uranium into lead"},{"text":"Hydrogen into helium"},{"text":"Carbon into oxygen"},{"text":"Helium into hydrogen"}]'::jsonb, 1, 'The Sun fuses hydrogen nuclei into helium, releasing energy.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'b65d70f1027eb45fd06ebdfbbe00af72'),
  ('igcse.mathematics', 'number', 'igcse.mathematics/number/standard-form-indices', 'mcq', null, 'Write 0.000 473 in standard form.', '[{"text":"4.73 × 10⁻⁴"},{"text":"4.73 × 10⁴"},{"text":"47.3 × 10⁻⁵"},{"text":"4.73 × 10⁻³"}]'::jsonb, 0, 'Move the decimal point 4 places right to get 4.73, so the power is −4.', 2, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '9ac2cd03a6ede6008f8cb20b313836fe'),
  ('igcse.mathematics', 'number', 'igcse.mathematics/number/factors-primes', 'mcq', null, 'What is the highest common factor (HCF) of 84 and 126?', '[{"text":"14"},{"text":"21"},{"text":"42"},{"text":"252"}]'::jsonb, 2, '84 = 2² × 3 × 7 and 126 = 2 × 3² × 7. HCF = 2 × 3 × 7 = 42.', 3, 'apply', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '488bfe9db644b6f7dba07ff471f8a03b'),
  ('igcse.mathematics', 'number', 'igcse.mathematics/number/factors-primes', 'mcq', null, 'What is the lowest common multiple (LCM) of 12 and 18?', '[{"text":"6"},{"text":"36"},{"text":"72"},{"text":"216"}]'::jsonb, 1, '12 = 2² × 3, 18 = 2 × 3². LCM = 2² × 3² = 36.', 2, 'apply', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'b8c8b4fd7869fb03c832938773055f7a'),
  ('igcse.mathematics', 'number', 'igcse.mathematics/number/percentages', 'mcq', null, 'A price of $80 is increased by 15%. What is the new price?', '[{"text":"$92"},{"text":"$95"},{"text":"$68"},{"text":"$12"}]'::jsonb, 0, '$80 × 1.15 = $92.', 2, 'apply', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'e2954a798663152b424d42354d548d56'),
  ('igcse.mathematics', 'number', 'igcse.mathematics/number/percentages', 'mcq', null, 'After a 20% reduction, a jacket costs $56. What was the original price?', '[{"text":"$67.20"},{"text":"$70"},{"text":"$44.80"},{"text":"$76"}]'::jsonb, 1, '$56 is 80% of the original: 56 ÷ 0.8 = $70. Adding 20% to $56 is a common mistake.', 4, 'understand', 'extended', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '08e9cf152361089741dade51226645c5'),
  ('igcse.mathematics', 'number', 'igcse.mathematics/number/ratio-proportion', 'mcq', null, 'Share $240 in the ratio 3 : 5.', '[{"text":"$80 and $160"},{"text":"$90 and $150"},{"text":"$72 and $168"},{"text":"$100 and $140"}]'::jsonb, 1, '8 parts in total, so one part is $30: 3 × 30 = $90 and 5 × 30 = $150.', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '876955d709623afeed80158466d33f53'),
  ('igcse.mathematics', 'number', 'igcse.mathematics/number/standard-form-indices', 'mcq', null, 'Evaluate 2⁻³.', '[{"text":"−8"},{"text":"−6"},{"text":"1/8"},{"text":"1/6"}]'::jsonb, 2, 'A negative power means a reciprocal: 2⁻³ = 1/2³ = 1/8.', 3, 'apply', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '938242348fabc2c958ce82295541e6cb'),
  ('igcse.mathematics', 'number', 'igcse.mathematics/number/rounding-bounds', 'mcq', null, 'Round 3.0485 to 3 significant figures.', '[{"text":"3.04"},{"text":"3.05"},{"text":"3.049"},{"text":"3.0"}]'::jsonb, 1, 'The first three significant figures are 3, 0, 4; the next digit is 8, so round up to 3.05.', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '603101efef59d65de20906bac780495a'),
  ('igcse.mathematics', 'number', 'igcse.mathematics/number/rounding-bounds', 'mcq', null, 'A length is 12 cm, correct to the nearest centimetre. What is its lower bound?', '[{"text":"11 cm"},{"text":"11.5 cm"},{"text":"11.9 cm"},{"text":"12.5 cm"}]'::jsonb, 1, 'The lower bound is half a unit below: 12 − 0.5 = 11.5 cm.', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'fbbaf340f160a2378d7041acc0339c27'),
  ('igcse.mathematics', 'number', 'igcse.mathematics/number/percentages', 'mcq', null, '$2 000 is invested at 3% compound interest per year. What is it worth after 2 years?', '[{"text":"$2 120.00"},{"text":"$2 121.80"},{"text":"$2 060.00"},{"text":"$2 180.00"}]'::jsonb, 1, '$2 000 × 1.03² = $2 121.80. Simple interest would give $2 120.', 4, 'understand', 'extended', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'e23d3691ddce36aaf8fc124021937fc5'),
  ('igcse.mathematics', 'number', 'igcse.mathematics/number/fractions-surds', 'mcq', null, 'Which of these is irrational?', '[{"text":"√49"},{"text":"0.25"},{"text":"√7"},{"text":"3/11"}]'::jsonb, 2, '√7 cannot be written as a fraction of integers. √49 = 7, and 3/11 is a recurring decimal, which is rational.', 3, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '7fe0b323d29454122bd95fca3b800ef1'),
  ('igcse.mathematics', 'number', 'igcse.mathematics/number/fractions-surds', 'mcq', null, 'Simplify √50.', '[{"text":"5√2"},{"text":"2√5"},{"text":"25√2"},{"text":"10√5"}]'::jsonb, 0, '√50 = √(25 × 2) = 5√2.', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '1a4af7c088e05c7bd3af4f33d5d616d2'),
  ('igcse.mathematics', 'algebra', 'igcse.mathematics/algebra/quadratics', 'mcq', null, 'Solve: x² − 5x + 6 = 0', '[{"text":"x = 1 and 6"},{"text":"x = 2 and 3"},{"text":"x = −2 and −3"},{"text":"x = −1 and −6"}]'::jsonb, 1, 'Factorise: (x−2)(x−3) = 0. So x = 2 or x = 3. Check: 2²−5(2)+6 = 0 ✓', 3, 'apply', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'fd6ffd34bd9ddc7be404da2ab3ab8825'),
  ('igcse.mathematics', 'algebra', 'igcse.mathematics/algebra/linear-equations', 'mcq', null, 'Solve: 2x + 3 = 11', '[{"text":"x = 7"},{"text":"x = 5.5"},{"text":"x = 4"},{"text":"x = 3"}]'::jsonb, 2, '2x = 11 − 3 = 8. x = 8/2 = 4', 2, 'apply', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '0fb0a7d6cbcc88f72e8a64d3d70b3af2'),
  ('igcse.mathematics', 'algebra', 'igcse.mathematics/algebra/quadratics', 'mcq', null, 'Simplify: (x²y³) ÷ (xy)', '[{"text":"xy²"},{"text":"x²y²"},{"text":"xy"},{"text":"x²y"}]'::jsonb, 0, 'x²y³ / xy = x^(2-1) · y^(3-1) = xy²', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '3173fbd64d990f81296c8653785f04ed'),
  ('igcse.mathematics', 'algebra', 'igcse.mathematics/algebra/functions', 'mcq', null, 'If f(x) = 2x² − 3, what is f(3)?', '[{"text":"12"},{"text":"9"},{"text":"15"},{"text":"18"}]'::jsonb, 2, 'f(3) = 2(3)² − 3 = 2(9) − 3 = 18 − 3 = 15', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '19ead0e4dadfd3b64b8d0558557983f8'),
  ('igcse.mathematics', 'geometry', 'igcse.mathematics/geometry/mensuration', 'mcq', null, 'Area of a circle with radius 5?', '[{"text":"10π"},{"text":"5π"},{"text":"25π"},{"text":"50π"}]'::jsonb, 2, 'A = πr² = π × 5² = 25π ≈ 78.54', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '98d7d55ddd7484ecff35af83b35023a8'),
  ('igcse.mathematics', 'geometry', 'igcse.mathematics/geometry/pythagoras-trig', 'mcq', null, 'In a right triangle, a=3, b=4. Find hypotenuse c.', '[{"text":"7"},{"text":"25"},{"text":"5"},{"text":"12"}]'::jsonb, 2, 'Pythagoras: c² = a² + b² = 9 + 16 = 25. c = 5. The 3-4-5 Pythagorean triple!', 2, 'apply', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'dd568c5e9747771456b81bb4cb3ba2f9'),
  ('igcse.mathematics', 'geometry', 'igcse.mathematics/geometry/angles', 'mcq', null, 'Interior angles of any triangle sum to:', '[{"text":"90°"},{"text":"180°"},{"text":"270°"},{"text":"360°"}]'::jsonb, 1, 'All triangles: angle sum = 180°. Quadrilaterals = 360°. Regular polygon: (n−2)×180°', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'f56d2e8dee7e9e336e84e5dc35eeb138'),
  ('igcse.mathematics', 'geometry', 'igcse.mathematics/geometry/coordinates', 'mcq', null, 'Midpoint of (2,4) and (8,10) is:', '[{"text":"(6,14)"},{"text":"(3,5)"},{"text":"(4,6)"},{"text":"(5,7)"}]'::jsonb, 3, 'Midpoint = ((x₁+x₂)/2, (y₁+y₂)/2) = ((2+8)/2, (4+10)/2) = (5, 7)', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'e3164865866b33a97d2f5150f5440eab'),
  ('igcse.mathematics', 'algebra', 'igcse.mathematics/algebra/graphs', 'mcq', null, 'Slope of the line y = 3x + 7 is:', '[{"text":"7"},{"text":"10"},{"text":"−3"},{"text":"3"}]'::jsonb, 3, 'In y = mx + c, m is the slope (gradient) and c is the y-intercept. Here m = 3.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '00d450b0d8a77f79fd0265f27db97855'),
  ('igcse.mathematics', 'statistics', 'igcse.mathematics/statistics/averages', 'mcq', null, 'Mean of {2, 4, 6, 8, 10}:', '[{"text":"5"},{"text":"30"},{"text":"4"},{"text":"6"}]'::jsonb, 3, 'Mean = (2+4+6+8+10)/5 = 30/5 = 6', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'a21ce94aababa1ea5ba4345ee46b6da6'),
  ('igcse.mathematics', 'statistics', 'igcse.mathematics/statistics/averages', 'mcq', null, 'Mode of {1, 2, 2, 3, 4}:', '[{"text":"1"},{"text":"3"},{"text":"4"},{"text":"2"}]'::jsonb, 3, 'Mode is the value that appears most often. 2 appears twice, all others once.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '1c041c3e2432d412c2becc63c2a20382'),
  ('igcse.mathematics', 'statistics', 'igcse.mathematics/statistics/averages', 'mcq', null, 'Standard deviation measures:', '[{"text":"Average value"},{"text":"Most common value"},{"text":"Middle value"},{"text":"Spread of data around the mean"}]'::jsonb, 3, 'Standard deviation measures how much data points vary from the mean. Higher SD = more spread out.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '6c634344b7dca35721a0b3b3d8287888'),
  ('igcse.computer-science', 'data-representation', 'igcse.computer-science/data-representation/hardware', 'mcq', null, 'What does CPU stand for?', '[{"text":"Central Processing Unit"},{"text":"Computer Power Unit"},{"text":"Central Print Utility"},{"text":"Core Programming Unit"}]'::jsonb, 0, 'The CPU (Central Processing Unit) executes instructions — the computer''s ''brain''.', 2, 'recall', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '3b9353e7be468d131ff141f2b5d187ef'),
  ('igcse.computer-science', 'data-representation', 'igcse.computer-science/data-representation/number-systems', 'mcq', null, 'In binary, what is the decimal number 2?', '[{"text":"01"},{"text":"10"},{"text":"11"},{"text":"00"}]'::jsonb, 1, 'Decimal 2 is ''10'' in binary (1×2 + 0×1).', 3, 'apply', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '333f14a9d3d6d23dd70479f8a93e1380'),
  ('igcse.computer-science', 'data-representation', 'igcse.computer-science/data-representation/storage', 'mcq', null, 'Which is a unit of digital storage?', '[{"text":"Hertz"},{"text":"Byte"},{"text":"Volt"},{"text":"Watt"}]'::jsonb, 1, 'A byte (8 bits) is the basic unit of digital storage.', 2, 'recall', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '5ff974e01bf1f2a67dcefa121b012fdf'),
  ('igcse.computer-science', 'data-representation', 'igcse.computer-science/data-representation/storage', 'mcq', null, 'RAM is best described as:', '[{"text":"Permanent storage"},{"text":"Temporary working memory"},{"text":"A type of CPU"},{"text":"A network cable"}]'::jsonb, 1, 'RAM is fast, temporary memory cleared when power is lost.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '5dbc1b41f366d44adb40a94e6abe98c2'),
  ('igcse.computer-science', 'data-representation', 'igcse.computer-science/data-representation/number-systems', 'mcq', null, 'What is the denary (decimal) value of the binary number 1011 0110?', '[{"text":"182"},{"text":"178"},{"text":"118"},{"text":"214"}]'::jsonb, 0, '128 + 32 + 16 + 4 + 2 = 182. Add the place values of each 1 bit.', 3, 'apply', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '36e20900e0dac65103729f1c3868e300'),
  ('igcse.computer-science', 'data-representation', 'igcse.computer-science/data-representation/number-systems', 'mcq', null, 'What is the hexadecimal value of the binary number 1110 0101?', '[{"text":"D5"},{"text":"E5"},{"text":"E4"},{"text":"C5"}]'::jsonb, 1, 'Split into nibbles: 1110 = E (14) and 0101 = 5, so the value is E5.', 3, 'apply', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '8bc3a3aaa954414fa851ad23cad281c9'),
  ('igcse.computer-science', 'data-representation', 'igcse.computer-science/data-representation/number-systems', 'mcq', null, 'How many different values can be represented with 8 bits?', '[{"text":"8"},{"text":"128"},{"text":"255"},{"text":"256"}]'::jsonb, 3, '2⁸ = 256 values, from 0 to 255. A common mistake is to answer 255, the largest value.', 2, 'apply', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '0bbaf2ff2a61623a8a30f56f12a8221e'),
  ('igcse.computer-science', 'data-representation', 'igcse.computer-science/data-representation/file-size', 'mcq', null, 'An image is 800 × 600 pixels with a colour depth of 24 bits. What is the file size, before compression?', '[{"text":"1 440 000 bytes"},{"text":"480 000 bytes"},{"text":"11 520 000 bytes"},{"text":"14 400 bytes"}]'::jsonb, 0, '800 × 600 × 24 = 11 520 000 bits; ÷ 8 = 1 440 000 bytes.', 4, 'apply', 'extended', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '79e4fbc3b8506c9595f696000ee0af47'),
  ('igcse.computer-science', 'data-representation', 'igcse.computer-science/data-representation/compression', 'mcq', null, 'Which statement about lossy compression is correct?', '[{"text":"The original file can be reconstructed exactly"},{"text":"It permanently removes some data to reduce file size"},{"text":"It is only used for text files"},{"text":"It always produces larger files than lossless compression"}]'::jsonb, 1, 'Lossy compression discards data (e.g. detail the eye cannot see), so the original cannot be restored exactly.', 3, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '0939551bc9d39de9ac01c8d59939420b'),
  ('igcse.computer-science', 'data-representation', 'igcse.computer-science/data-representation/hardware', 'mcq', null, 'Which register holds the address of the next instruction to be fetched?', '[{"text":"Memory Data Register (MDR)"},{"text":"Accumulator (ACC)"},{"text":"Program Counter (PC)"},{"text":"Current Instruction Register (CIR)"}]'::jsonb, 2, 'The Program Counter stores the address of the next instruction and is incremented during the fetch stage.', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '5e2573827d455a4fd2f85cd99e00a3d3'),
  ('igcse.computer-science', 'data-representation', 'igcse.computer-science/data-representation/number-systems', 'mcq', null, 'What is the result of a logical left shift of 0001 1010 by two places?', '[{"text":"0110 1000"},{"text":"0000 0110"},{"text":"0011 0100"},{"text":"1010 0000"}]'::jsonb, 0, 'Each bit moves two places left and zeros fill from the right: 0001 1010 → 0110 1000 (26 × 4 = 104).', 4, 'apply', 'extended', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '6c6b08fbadd66a67fbe0d9b8ee583f0b'),
  ('igcse.computer-science', 'data-representation', 'igcse.computer-science/data-representation/error-detection', 'mcq', null, 'Why is a parity bit added to a byte before transmission?', '[{"text":"To encrypt the data"},{"text":"To detect some transmission errors"},{"text":"To compress the data"},{"text":"To identify the receiving device"}]'::jsonb, 1, 'A parity bit makes the number of 1s odd or even, so a single flipped bit can be detected.', 3, 'analyse', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '2274ccc381ab1f94c1288fb6de1fa490'),
  ('igcse.computer-science', 'data-representation', 'igcse.computer-science/data-representation/storage', 'mcq', null, 'Which type of storage is non-volatile?', '[{"text":"RAM"},{"text":"Cache"},{"text":"Registers"},{"text":"Solid-state drive (SSD)"}]'::jsonb, 3, 'An SSD keeps its data without power. RAM, cache and registers lose their contents when power is removed.', 2, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'd71091e240510c3a52c006b30eed5363'),
  ('igcse.computer-science', 'data-representation', 'igcse.computer-science/data-representation/number-systems', 'mcq', null, 'In two’s complement 8-bit binary, what is −5?', '[{"text":"1000 0101"},{"text":"1111 1011"},{"text":"1111 1010"},{"text":"0000 0101"}]'::jsonb, 1, 'Write +5 (0000 0101), invert the bits (1111 1010) and add 1: 1111 1011.', 4, 'understand', 'extended', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '075c7b83112a9b8bc1e0950f51633a22'),
  ('igcse.computer-science', 'networks', 'igcse.computer-science/networks/internet-protocols', 'mcq', null, 'What does ''WWW'' stand for?', '[{"text":"World Wide Web"},{"text":"Web Wire Width"},{"text":"Wide World Web"},{"text":"World Web Wire"}]'::jsonb, 0, 'WWW stands for the World Wide Web.', 2, 'recall', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '72ebdbdff665b16ebc5bfb2bf2aa0fb5'),
  ('igcse.computer-science', 'networks', 'igcse.computer-science/networks/network-devices', 'mcq', null, 'An IP address is used to:', '[{"text":"Style a webpage"},{"text":"Identify a device on a network"},{"text":"Store files"},{"text":"Run programs"}]'::jsonb, 1, 'An IP address uniquely identifies a device on a network.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '88c9268e782be3792e9bfa43cf26ad6d'),
  ('igcse.computer-science', 'networks', 'igcse.computer-science/networks/network-devices', 'mcq', null, 'What is the main role of a router?', '[{"text":"To connect devices within a single LAN only"},{"text":"To forward data packets between different networks"},{"text":"To store web pages"},{"text":"To convert analogue signals to digital"}]'::jsonb, 1, 'A router reads the destination IP address of a packet and forwards it towards another network.', 2, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'bac32b52e45161381fd1fc67207348ca'),
  ('igcse.computer-science', 'networks', 'igcse.computer-science/networks/internet-protocols', 'mcq', null, 'Which protocol is used to transfer web pages securely?', '[{"text":"FTP"},{"text":"HTTP"},{"text":"HTTPS"},{"text":"SMTP"}]'::jsonb, 2, 'HTTPS is HTTP carried over an encrypted TLS connection.', 2, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'af46037b9e11aae0dd0bb726e9f0a6f9'),
  ('igcse.computer-science', 'networks', 'igcse.computer-science/networks/network-devices', 'mcq', null, 'What is a MAC address?', '[{"text":"An address assigned by a DNS server"},{"text":"A unique identifier given to a network interface card by the manufacturer"},{"text":"The IP address of a website"},{"text":"A password for a wireless network"}]'::jsonb, 1, 'A MAC address is a 48-bit identifier set by the manufacturer; unlike an IP address it does not change between networks.', 3, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '45f30bc48ce37a19fed0df6ed40b321e'),
  ('igcse.computer-science', 'networks', 'igcse.computer-science/networks/network-devices', 'mcq', null, 'What does the Domain Name System (DNS) do?', '[{"text":"Encrypts data sent between devices"},{"text":"Translates a domain name into an IP address"},{"text":"Assigns MAC addresses"},{"text":"Blocks unauthorised traffic"}]'::jsonb, 1, 'DNS looks up the IP address that corresponds to a human-readable name such as example.com.', 2, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'a98dff1f4fec622bc8688b3fe03f2d91'),
  ('igcse.computer-science', 'networks', 'igcse.computer-science/networks/transmission', 'mcq', null, 'Which is a feature of packet switching?', '[{"text":"All packets must follow the same route"},{"text":"Packets may take different routes and are reassembled at the destination"},{"text":"A dedicated line is kept open for the whole transmission"},{"text":"Packets never need to be reordered"}]'::jsonb, 1, 'Each packet is routed independently, so packets can arrive out of order and are reassembled using their sequence numbers.', 3, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'fc9eacb343a2d009dfd4d9029676347f'),
  ('igcse.computer-science', 'networks', 'igcse.computer-science/networks/cyber-security', 'mcq', null, 'A firewall is best described as:', '[{"text":"Software or hardware that monitors and filters traffic using rules"},{"text":"A device that boosts Wi-Fi signal strength"},{"text":"A backup of network data"},{"text":"A program that removes viruses from files"}]'::jsonb, 0, 'A firewall compares incoming and outgoing traffic against rules and blocks what is not allowed.', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '627de74d5bf6080cfcf4c9d554da5158'),
  ('igcse.computer-science', 'networks', 'igcse.computer-science/networks/cyber-security', 'mcq', null, 'What is phishing?', '[{"text":"Flooding a server with requests"},{"text":"Sending fake messages that trick users into revealing personal details"},{"text":"Recording keystrokes with hardware"},{"text":"Guessing passwords with every possible combination"}]'::jsonb, 1, 'Phishing uses legitimate-looking emails or messages to lure people into giving away data such as passwords.', 2, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '23af9d8bdda42f5e5e09deffd9305e79'),
  ('igcse.computer-science', 'networks', 'igcse.computer-science/networks/transmission', 'mcq', null, 'Which transmission method sends several bits at the same time over multiple wires?', '[{"text":"Serial"},{"text":"Parallel"},{"text":"Simplex"},{"text":"Half-duplex"}]'::jsonb, 1, 'Parallel transmission sends bits simultaneously; it is fast but suffers skew over long distances, so serial is used for long links.', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '06194043d7e4a429f449ce3f116f9704'),
  ('igcse.computer-science', 'algorithms', 'igcse.computer-science/algorithms/computational-thinking', 'mcq', null, 'An algorithm is best described as:', '[{"text":"A type of computer"},{"text":"A step-by-step set of instructions"},{"text":"A programming language"},{"text":"A storage device"}]'::jsonb, 1, 'An algorithm is a finite sequence of steps that solves a problem.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '617219f65e398beeac6c2d4257a3e66d'),
  ('igcse.computer-science', 'algorithms', 'igcse.computer-science/algorithms/search-sort', 'mcq', null, 'Putting items in order, like A-Z, is called:', '[{"text":"Searching"},{"text":"Sorting"},{"text":"Compiling"},{"text":"Encrypting"}]'::jsonb, 1, 'Sorting arranges data into a defined order.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'cfbbabb27f756400081acccf187e9434'),
  ('igcse.computer-science', 'algorithms', 'igcse.computer-science/algorithms/search-sort', 'mcq', null, 'A linear search is performed on an unsorted list of 1 000 items. What is the maximum number of comparisons needed?', '[{"text":"10"},{"text":"500"},{"text":"999"},{"text":"1 000"}]'::jsonb, 3, 'In the worst case the item is last (or absent), so all 1 000 items are compared.', 3, 'apply', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'f4af6ae00ac85678170bfd45f70f1af6'),
  ('igcse.computer-science', 'algorithms', 'igcse.computer-science/algorithms/search-sort', 'mcq', null, 'After the first pass of a bubble sort (ascending) on [5, 1, 4, 2, 8], what is the list?', '[{"text":"[1, 4, 2, 5, 8]"},{"text":"[1, 2, 4, 5, 8]"},{"text":"[1, 5, 4, 2, 8]"},{"text":"[5, 1, 4, 2, 8]"}]'::jsonb, 0, 'Compare adjacent pairs and swap when out of order: the largest unsorted value (5) moves up until it meets 8: [1, 4, 2, 5, 8].', 4, 'apply', 'extended', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '3b8be5ff88aee8f3031ea61207bab268'),
  ('igcse.computer-science', 'algorithms', 'igcse.computer-science/algorithms/validation-testing', 'mcq', null, 'Which type of validation checks that a value falls between a minimum and a maximum?', '[{"text":"Length check"},{"text":"Type check"},{"text":"Range check"},{"text":"Presence check"}]'::jsonb, 2, 'A range check rejects values outside the allowed bounds, for example a month number outside 1–12.', 2, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '0597384b9825ed61970dc3d26363ccca'),
  ('igcse.computer-science', 'algorithms', 'igcse.computer-science/algorithms/validation-testing', 'mcq', null, 'What is the difference between validation and verification?', '[{"text":"They mean the same thing"},{"text":"Validation checks data is reasonable; verification checks it was copied or entered accurately"},{"text":"Verification checks data is reasonable; validation checks it was entered accurately"},{"text":"Validation is only done by humans"}]'::jsonb, 1, 'Validation tests data against rules (sensible); verification (double entry, visual check) confirms it matches the source.', 3, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'd73ef04d9e35788f39173db3ffb015ca'),
  ('igcse.computer-science', 'algorithms', 'igcse.computer-science/algorithms/trace-tables', 'mcq', null, 'What does a trace table help a programmer do?', '[{"text":"Compile the program faster"},{"text":"Record the values of variables as an algorithm runs, to find errors"},{"text":"Encrypt the program"},{"text":"Draw a flowchart automatically"}]'::jsonb, 1, 'Dry-running with a trace table shows how variables change step by step, revealing logic errors.', 2, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '08a3ec9242bb78246df878364c586e84'),
  ('igcse.computer-science', 'algorithms', 'igcse.computer-science/algorithms/validation-testing', 'mcq', null, 'Which data would be best to test the boundary of "age must be 13 to 19 inclusive"?', '[{"text":"15"},{"text":"-3 and \"abc\""},{"text":"12, 13, 19 and 20"},{"text":"100"}]'::jsonb, 2, 'Boundary testing uses values at and just beyond each limit: 12 and 20 should be rejected, 13 and 19 accepted.', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'c7120323eb31a250614cecba21d3b46a'),
  ('igcse.computer-science', 'algorithms', 'igcse.computer-science/algorithms/computational-thinking', 'mcq', null, 'Decomposition in computational thinking means:', '[{"text":"Removing unnecessary detail"},{"text":"Breaking a problem into smaller sub-problems"},{"text":"Converting code into machine code"},{"text":"Sorting data into order"}]'::jsonb, 1, 'Decomposition splits a complex problem into manageable parts. Removing detail is abstraction.', 2, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '9ee689d5074e6468402b34fe26ebe152'),
  ('igcse.computer-science', 'algorithms', 'igcse.computer-science/algorithms/search-sort', 'mcq', null, 'A binary search is used on a sorted list of 64 items. What is the maximum number of comparisons?', '[{"text":"6"},{"text":"7"},{"text":"32"},{"text":"64"}]'::jsonb, 1, 'Each comparison halves the search space: 64 → 32 → 16 → 8 → 4 → 2 → 1, so at most 7 comparisons (log₂64 + 1).', 4, 'apply', 'extended', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'df15ac34f571d141994202f5b0c9f0eb'),
  ('igcse.computer-science', 'programming', 'igcse.computer-science/programming/data-types', 'mcq', null, 'What does a ''variable'' do in programming?', '[{"text":"Stores a value"},{"text":"Deletes data"},{"text":"Prints text"},{"text":"Stops the program"}]'::jsonb, 0, 'A variable is a named container that stores a value you can use and change.', 2, 'recall', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '46d1486d1bdc7fa0dc8722ab2a39b824'),
  ('igcse.computer-science', 'programming', 'igcse.computer-science/programming/selection-iteration', 'mcq', null, 'Which of these is a loop structure?', '[{"text":"if"},{"text":"for"},{"text":"return"},{"text":"print"}]'::jsonb, 1, 'A ''for'' loop repeats a block of code a set number of times.', 2, 'recall', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'cef920152fe6c5591000e36cfbfbd541'),
  ('igcse.computer-science', 'programming', 'igcse.computer-science/programming/data-types', 'mcq', null, 'What is the output type of a comparison like 5 > 3?', '[{"text":"Integer"},{"text":"String"},{"text":"Boolean"},{"text":"Float"}]'::jsonb, 2, 'Comparisons return a Boolean: true or false.', 3, 'apply', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'a142e6ae4cdabb115609a4ea1907e7e6'),
  ('igcse.computer-science', 'programming', 'igcse.computer-science/programming/operators', 'mcq', null, 'In code, ''=='' usually means:', '[{"text":"Assignment"},{"text":"Comparison (equality)"},{"text":"Addition"},{"text":"A comment"}]'::jsonb, 1, '''=='' checks equality; a single ''='' assigns a value.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'a243d69648dcf70b0060b997b9b99886'),
  ('igcse.computer-science', 'programming', 'igcse.computer-science/programming/operators', 'mcq', null, 'What is the value of 17 MOD 5?', '[{"text":"3"},{"text":"2"},{"text":"3.4"},{"text":"85"}]'::jsonb, 1, 'MOD gives the remainder: 17 = 3 × 5 + 2, so 17 MOD 5 = 2. (17 DIV 5 = 3.)', 2, 'apply', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '61970852fcdf7f68f5cf362d4e7c21d7'),
  ('igcse.computer-science', 'programming', 'igcse.computer-science/programming/selection-iteration', 'mcq', null, 'Which loop is most suitable when the number of repetitions is known in advance?', '[{"text":"A count-controlled loop (FOR)"},{"text":"A pre-condition loop (WHILE)"},{"text":"A post-condition loop (REPEAT … UNTIL)"},{"text":"An IF statement"}]'::jsonb, 0, 'A FOR loop runs a fixed number of times; WHILE and REPEAT loops continue until a condition changes.', 2, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'a6ab21e2bdf77e657afdf496d1af6d18'),
  ('igcse.computer-science', 'programming', 'igcse.computer-science/programming/selection-iteration', 'mcq', null, 'What is the difference between a WHILE loop and a REPEAT … UNTIL loop?', '[{"text":"There is no difference"},{"text":"A REPEAT loop always runs at least once because the condition is tested at the end"},{"text":"A WHILE loop always runs at least once"},{"text":"REPEAT loops cannot contain IF statements"}]'::jsonb, 1, 'WHILE tests before the body (may run zero times); REPEAT … UNTIL tests after the body, so it always runs at least once.', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'f13cc145d0cf2bb0a38e642521f373fc'),
  ('igcse.computer-science', 'programming', 'igcse.computer-science/programming/data-types', 'mcq', null, 'Which data type is most appropriate for storing a telephone number such as 0044 7700 900123?', '[{"text":"Integer"},{"text":"Real"},{"text":"String"},{"text":"Boolean"}]'::jsonb, 2, 'Phone numbers are not used in calculations and can have leading zeros and spaces, so a string is correct.', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '06a1f27e14f3edeea4e06a3dceb02d2b'),
  ('igcse.computer-science', 'programming', 'igcse.computer-science/programming/arrays', 'mcq', null, 'In a one-dimensional array Scores[1:10], how many elements can be stored?', '[{"text":"9"},{"text":"10"},{"text":"11"},{"text":"1"}]'::jsonb, 1, 'The indices run from 1 to 10 inclusive, giving 10 elements.', 2, 'apply', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '681a373b9cc805a060ff1d5347742a3e'),
  ('igcse.computer-science', 'programming', 'igcse.computer-science/programming/subroutines', 'mcq', null, 'What is the purpose of a procedure (subroutine)?', '[{"text":"To store data permanently"},{"text":"To group a set of statements under a name so they can be reused"},{"text":"To end the program"},{"text":"To declare constants only"}]'::jsonb, 1, 'Subroutines make code reusable and easier to maintain; a function is a subroutine that returns a value.', 2, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '7961de0cbbf4643d63f1dbae0fa50b06'),
  ('igcse.computer-science', 'programming', 'igcse.computer-science/programming/selection-iteration', 'mcq', null, 'What is output by: Total ← 0; FOR i ← 1 TO 4: Total ← Total + i; NEXT i; OUTPUT Total', '[{"text":"4"},{"text":"6"},{"text":"10"},{"text":"0"}]'::jsonb, 2, '0 + 1 + 2 + 3 + 4 = 10.', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'f8414e18afb9c216a37162874282a2f8'),
  ('igcse.computer-science', 'programming', 'igcse.computer-science/programming/errors', 'mcq', null, 'Which is an example of a logic error?', '[{"text":"Misspelling a keyword so the program will not run"},{"text":"Using > instead of >= so a value on the boundary is handled wrongly"},{"text":"Running out of memory"},{"text":"Forgetting a closing bracket"}]'::jsonb, 1, 'A logic error lets the program run but produces the wrong result; misspellings and missing brackets are syntax errors.', 3, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'bf6f7fde691abff2e68fabf81641aef4'),
  ('igcse.computer-science', 'programming', 'igcse.computer-science/programming/databases-sql', 'mcq', null, 'Which SQL statement returns the names of students older than 16 from a table called Students?', '[{"text":"SELECT Name FROM Students WHERE Age > 16;"},{"text":"GET Name IN Students IF Age > 16;"},{"text":"SELECT Students FROM Name WHERE Age > 16;"},{"text":"FIND Name WHERE Students > 16;"}]'::jsonb, 0, 'SELECT lists the fields, FROM names the table and WHERE filters the records.', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'b9d430e6fac5e4b7e7871ec24c5f71ed'),
  ('igcse.economics', 'markets', 'igcse.economics/markets/demand-supply', 'mcq', null, 'When demand rises and supply stays the same, price usually:', '[{"text":"Falls"},{"text":"Rises"},{"text":"Stays the same"},{"text":"Becomes zero"}]'::jsonb, 1, 'Higher demand with fixed supply pushes the equilibrium price up.', 3, 'recall', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'c2f5d368eae99d257a087b428a4e1dac'),
  ('igcse.economics', 'micro', 'igcse.economics/micro/decision-makers', 'mcq', null, 'The study of individual markets and consumer choices is:', '[{"text":"Macroeconomics"},{"text":"Microeconomics"},{"text":"Statistics"},{"text":"Accounting"}]'::jsonb, 1, 'Microeconomics focuses on individual agents — consumers and firms.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'de1880fbd0a91ee1b357e5e946402a36'),
  ('igcse.economics', 'markets', 'igcse.economics/markets/price-determination', 'mcq', null, 'A situation where one seller dominates a market is a:', '[{"text":"Monopoly"},{"text":"Democracy"},{"text":"Surplus"},{"text":"Subsidy"}]'::jsonb, 0, 'A monopoly is a market with a single dominant supplier.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'ba60de4f3a693e96fbb7d506eed8974f'),
  ('igcse.economics', 'micro', 'igcse.economics/micro/scarcity-choice', 'mcq', null, 'Opportunity cost is best defined as:', '[{"text":"The money price of a good"},{"text":"The next best alternative given up when a choice is made"},{"text":"The total cost of production"},{"text":"The cost of borrowing money"}]'::jsonb, 1, 'Because resources are scarce, every choice means giving up the next best alternative.', 2, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'c69d5259ffd3cde7b2916c5505571a20'),
  ('igcse.economics', 'micro', 'igcse.economics/micro/elasticity', 'mcq', null, 'The price of a good rises by 10% and quantity demanded falls by 25%. The price elasticity of demand is:', '[{"text":"−0.4"},{"text":"−2.5"},{"text":"−0.25"},{"text":"−10"}]'::jsonb, 1, 'PED = %Δ quantity demanded ÷ %Δ price = −25 ÷ 10 = −2.5, so demand is price elastic.', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '64d1b0596abd4622dff809efb100d4e2'),
  ('igcse.economics', 'micro', 'igcse.economics/micro/elasticity', 'mcq', null, 'If demand for a product is price inelastic, a price rise will:', '[{"text":"Reduce total revenue"},{"text":"Increase total revenue"},{"text":"Leave quantity demanded unchanged"},{"text":"Always cause a shortage"}]'::jsonb, 1, 'With inelastic demand, quantity falls proportionally less than price rises, so revenue (P × Q) increases.', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '5d94c5609cf058836ba83edff4dd1a06'),
  ('igcse.economics', 'micro', 'igcse.economics/micro/costs-revenue', 'mcq', null, 'Which is an example of a fixed cost for a bakery?', '[{"text":"Flour"},{"text":"Electricity used by the ovens"},{"text":"Rent on the shop"},{"text":"Packaging"}]'::jsonb, 2, 'Rent does not change with output in the short run; ingredients and packaging are variable costs.', 2, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'a58aef0745e2186562788e94a16a1698'),
  ('igcse.economics', 'micro', 'igcse.economics/micro/costs-revenue', 'mcq', null, 'A firm produces 500 units with total costs of $4 000 and fixed costs of $1 500. What is the average variable cost?', '[{"text":"$8"},{"text":"$5"},{"text":"$3"},{"text":"$11"}]'::jsonb, 1, 'Variable cost = $4 000 − $1 500 = $2 500; ÷ 500 units = $5 per unit.', 4, 'apply', 'extended', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '8eac68ae83c15b8c2764131c9b0a8e5c'),
  ('igcse.economics', 'markets', 'igcse.economics/markets/demand-supply', 'mcq', null, 'Which factor would most likely increase the supply of wheat?', '[{"text":"A fall in the price of wheat"},{"text":"Favourable weather and a good harvest"},{"text":"An increase in the demand for bread"},{"text":"A new tax on farmers"}]'::jsonb, 1, 'Good weather raises output at every price, shifting supply to the right. A change in wheat’s own price is a movement along the curve.', 3, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '1a798affbf3230c50ac8ee82a2b9e986'),
  ('igcse.economics', 'micro', 'igcse.economics/micro/labour', 'mcq', null, 'Why might a worker’s wage be higher in one occupation than another?', '[{"text":"Because the job requires fewer skills"},{"text":"Because the supply of workers with the required skills is limited"},{"text":"Because demand for that labour is low"},{"text":"Because the job has better working conditions"}]'::jsonb, 1, 'Scarce skills mean low labour supply relative to demand, which pushes wages up.', 3, 'analyse', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '9792e63eba13b99785e7717a196c4b63'),
  ('igcse.economics', 'micro', 'igcse.economics/micro/decision-makers', 'mcq', null, 'Which is a main function of a commercial bank?', '[{"text":"Setting the interest rate for the whole economy"},{"text":"Accepting deposits and making loans to households and firms"},{"text":"Printing banknotes"},{"text":"Collecting taxes for the government"}]'::jsonb, 1, 'Commercial banks take deposits and lend; the central bank sets policy rates and issues currency.', 2, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '1cdd019c24f007bd1f9c895db8f79f67'),
  ('igcse.economics', 'markets', 'igcse.economics/markets/price-determination', 'mcq', null, 'The point where supply equals demand is called:', '[{"text":"Surplus"},{"text":"Shortage"},{"text":"Equilibrium"},{"text":"Deficit"}]'::jsonb, 2, 'Equilibrium is where the quantity supplied equals the quantity demanded.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '59e72b7ec71399ea376711141526c445'),
  ('igcse.economics', 'markets', 'igcse.economics/markets/demand-supply', 'mcq', null, 'If a product''s price rises, quantity demanded usually:', '[{"text":"Rises"},{"text":"Falls"},{"text":"Stays the same"},{"text":"Doubles"}]'::jsonb, 1, 'The law of demand: higher prices usually reduce quantity demanded.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '2045f714b972c6f671be5828612b2635'),
  ('igcse.economics', 'markets', 'igcse.economics/markets/price-determination', 'mcq', null, 'If the price of a good is set above the equilibrium price, the result is:', '[{"text":"A shortage"},{"text":"Excess supply (a surplus)"},{"text":"An increase in demand"},{"text":"Equilibrium"}]'::jsonb, 1, 'Above equilibrium, quantity supplied exceeds quantity demanded, creating a surplus.', 2, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '4f0673017e4b6d812d963ada159aa469'),
  ('igcse.economics', 'markets', 'igcse.economics/markets/demand-supply', 'mcq', null, 'Tea and coffee are substitutes. A rise in the price of coffee will most likely:', '[{"text":"Decrease the demand for tea"},{"text":"Increase the demand for tea"},{"text":"Decrease the supply of tea"},{"text":"Have no effect on tea"}]'::jsonb, 1, 'Consumers switch to the cheaper substitute, shifting the demand curve for tea to the right.', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'e89db3a74705caf2688da931aeea398e'),
  ('igcse.economics', 'markets', 'igcse.economics/markets/market-failure', 'mcq', null, 'Which is an example of a negative externality?', '[{"text":"A person getting a vaccine"},{"text":"Noise and pollution from a factory affecting local residents"},{"text":"A firm training its workers"},{"text":"A park that everyone can enjoy"}]'::jsonb, 1, 'Pollution imposes a cost on third parties who are not part of the transaction.', 2, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '1d64aa8aa01b176a61badb4dc514715d'),
  ('igcse.economics', 'markets', 'igcse.economics/markets/market-failure', 'mcq', null, 'Why are public goods usually not provided by the private sector?', '[{"text":"Because they are too cheap to produce"},{"text":"Because they are non-excludable, so people can benefit without paying (free riders)"},{"text":"Because nobody wants them"},{"text":"Because they are always harmful"}]'::jsonb, 1, 'Non-excludability and non-rivalry create the free-rider problem, so private firms cannot charge enough to profit.', 3, 'analyse', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '286c8ff010d463c27166c646c6215520'),
  ('igcse.economics', 'markets', 'igcse.economics/markets/price-determination', 'mcq', null, 'A government sets a maximum price for rent below the equilibrium. What is the likely effect?', '[{"text":"A surplus of rental housing"},{"text":"A shortage of rental housing"},{"text":"Rents rise above equilibrium"},{"text":"No effect on the market"}]'::jsonb, 1, 'A binding price ceiling raises quantity demanded and lowers quantity supplied, creating a shortage.', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '699dc4a0d2cc448a356c85d6e8083169'),
  ('igcse.economics', 'micro', 'igcse.economics/micro/scarcity-choice', 'mcq', null, 'What is the basic economic problem?', '[{"text":"Inflation"},{"text":"Unlimited wants but limited resources"},{"text":"Government debt"},{"text":"Unemployment"}]'::jsonb, 1, 'Scarcity: finite resources cannot satisfy unlimited wants, so choices must be made.', 2, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '3cdda9d47037d00409388e157f263cdd'),
  ('igcse.economics', 'markets', 'igcse.economics/markets/economic-systems', 'mcq', null, 'Which describes a market economic system?', '[{"text":"The government decides what to produce"},{"text":"Resources are allocated mainly through the price mechanism and private firms"},{"text":"All firms are owned by the state"},{"text":"Production is based only on tradition"}]'::jsonb, 1, 'In a market economy, supply and demand (prices) signal what to produce.', 2, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'c7997d4f8fd3d7314d1602c88a2ee148'),
  ('igcse.economics', 'macro', 'igcse.economics/macro/growth', 'mcq', null, 'GDP stands for:', '[{"text":"Gross Domestic Product"},{"text":"General Demand Price"},{"text":"Global Data Point"},{"text":"Gross Debt Percentage"}]'::jsonb, 0, 'GDP (Gross Domestic Product) measures the total value of goods and services produced.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'b26b58c9a2a27db620db144d8bf3b99a'),
  ('igcse.economics', 'macro', 'igcse.economics/macro/inflation', 'mcq', null, 'A general rise in prices across an economy is called:', '[{"text":"Deflation"},{"text":"Inflation"},{"text":"Recession"},{"text":"Surplus"}]'::jsonb, 1, 'Inflation is a sustained increase in the general price level.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'c2104e88de5be7d7f3691a96f2450553'),
  ('igcse.economics', 'macro', 'igcse.economics/macro/growth', 'mcq', null, 'A period of falling economic output and rising unemployment is a:', '[{"text":"Boom"},{"text":"Recession"},{"text":"Surplus"},{"text":"Subsidy"}]'::jsonb, 1, 'A recession is a significant, sustained decline in economic activity.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '52a2d59fb34edc3396ff2876394d14a0'),
  ('igcse.economics', 'macro', 'igcse.economics/macro/fiscal-monetary', 'mcq', null, 'Which is an example of expansionary fiscal policy?', '[{"text":"Raising interest rates"},{"text":"Cutting income tax"},{"text":"Reducing government spending"},{"text":"Selling government bonds to reduce money supply"}]'::jsonb, 1, 'Fiscal policy uses tax and government spending; cutting taxes raises disposable income and aggregate demand.', 3, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '2105ad148bfa6cb000f28b468d278754'),
  ('igcse.economics', 'macro', 'igcse.economics/macro/fiscal-monetary', 'mcq', null, 'A central bank raises interest rates. The most likely aim is to:', '[{"text":"Increase inflation"},{"text":"Reduce inflation"},{"text":"Increase borrowing"},{"text":"Weaken the exchange rate"}]'::jsonb, 1, 'Higher rates make borrowing dearer and saving more attractive, reducing spending and inflationary pressure.', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '5507038ee6dba4cbb0cd79b9e93b43e4'),
  ('igcse.economics', 'macro', 'igcse.economics/macro/unemployment', 'mcq', null, 'Structural unemployment is caused by:', '[{"text":"Seasonal changes in demand"},{"text":"A mismatch between workers’ skills and the jobs available as industries decline"},{"text":"Workers moving between jobs"},{"text":"A recession reducing demand across the economy"}]'::jsonb, 1, 'When an industry declines permanently, its workers’ skills may not match new jobs.', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '268a4abe31e6f8abc8c553d8deaf4444'),
  ('igcse.economics', 'macro', 'igcse.economics/macro/inflation', 'mcq', null, 'How is the inflation rate usually measured?', '[{"text":"By changes in GDP"},{"text":"By the change in a consumer price index (CPI)"},{"text":"By the unemployment rate"},{"text":"By the exchange rate"}]'::jsonb, 1, 'A CPI tracks the price of a weighted basket of goods and services bought by typical households.', 2, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'e6b48a9b2091aefd9c394ea798e1cd23'),
  ('igcse.economics', 'macro', 'igcse.economics/macro/inflation', 'mcq', null, 'Which is a likely cost of high inflation?', '[{"text":"Savers gain purchasing power"},{"text":"Fixed incomes lose purchasing power"},{"text":"Exports become cheaper"},{"text":"Borrowers pay more in real terms"}]'::jsonb, 1, 'People on fixed incomes can buy less as prices rise; borrowers tend to gain as the real value of debt falls.', 3, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '3d041c97b200e2dda9033afef0aef6af'),
  ('igcse.economics', 'macro', 'igcse.economics/macro/growth', 'mcq', null, 'Economic growth is best measured by:', '[{"text":"A rise in real GDP"},{"text":"A rise in nominal GDP"},{"text":"A rise in prices"},{"text":"A rise in population"}]'::jsonb, 0, 'Real GDP removes the effect of inflation, so it measures the increase in actual output.', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'd7f127bc011d5814e81e5458da0cd368'),
  ('igcse.economics', 'macro', 'igcse.economics/macro/taxation', 'mcq', null, 'A progressive tax is one where:', '[{"text":"Everyone pays the same amount"},{"text":"The proportion of income paid in tax rises as income rises"},{"text":"The poor pay a higher proportion"},{"text":"Only firms pay tax"}]'::jsonb, 1, 'Progressive taxes take a larger percentage from higher incomes, e.g. income tax with rising bands.', 2, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '44010902875d4dfadfbc2bb536fab16c'),
  ('igcse.economics', 'trade', 'igcse.economics/trade/money', 'mcq', null, 'The body that typically controls a country''s money supply is the:', '[{"text":"Stock market"},{"text":"Central bank"},{"text":"Supermarket"},{"text":"Parliament"}]'::jsonb, 1, 'The central bank manages money supply and interest rates.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '4ffbbe9d498de9b7f555462e31025121'),
  ('igcse.economics', 'trade', 'igcse.economics/trade/specialisation', 'mcq', null, 'Buying goods from another country is called:', '[{"text":"Exporting"},{"text":"Importing"},{"text":"Tariffing"},{"text":"Subsidizing"}]'::jsonb, 1, 'Importing is purchasing goods or services from abroad.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '3ab44b023f0623a469b24f007ba228b3'),
  ('igcse.economics', 'trade', 'igcse.economics/trade/exchange-rates', 'mcq', null, 'A country’s currency depreciates. What is the likely effect on its exports?', '[{"text":"They become more expensive abroad"},{"text":"They become cheaper abroad, so demand may rise"},{"text":"There is no effect"},{"text":"They are banned"}]'::jsonb, 1, 'Foreign buyers need less of their own currency to buy the exports, making them more competitive.', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '850b8d0fd4df16ba5e87a5dbb829f146'),
  ('igcse.economics', 'trade', 'igcse.economics/trade/specialisation', 'mcq', null, 'What is a tariff?', '[{"text":"A limit on the quantity of imports"},{"text":"A tax on imported goods"},{"text":"A subsidy to exporters"},{"text":"A ban on trade"}]'::jsonb, 1, 'A tariff is a tax on imports; a quota limits quantity.', 2, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'be4c95fb21ef4602b917de982e857254'),
  ('igcse.economics', 'trade', 'igcse.economics/trade/specialisation', 'mcq', null, 'Specialisation between countries is based on:', '[{"text":"Producing everything domestically"},{"text":"Concentrating on goods they can produce relatively efficiently and trading for others"},{"text":"Avoiding all imports"},{"text":"Having the largest population"}]'::jsonb, 1, 'Countries gain by specialising where their opportunity cost is lower and trading.', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'bef1e83481d4ecff82020e0cf4c84fa2'),
  ('igcse.economics', 'trade', 'igcse.economics/trade/exchange-rates', 'mcq', null, 'A current account deficit means that:', '[{"text":"The government spends more than it collects in taxes"},{"text":"The value of imports of goods and services (and income paid abroad) exceeds exports"},{"text":"Exports exceed imports"},{"text":"The currency has appreciated"}]'::jsonb, 1, 'The current account records trade in goods and services plus income flows; a deficit means more money flowing out than in.', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '8cf9bf90c0019b9a0e40101b4f7ca494'),
  ('igcse.economics', 'trade', 'igcse.economics/trade/money', 'mcq', null, 'Which is a function of money?', '[{"text":"A store of value"},{"text":"A source of pollution"},{"text":"A type of tax"},{"text":"A government policy"}]'::jsonb, 0, 'Money acts as a medium of exchange, a measure of value, a store of value and a standard of deferred payment.', 2, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'c283ad3f3d34cefc2a9dcda5bac72380'),
  ('igcse.economics', 'trade', 'igcse.economics/trade/protectionism', 'mcq', null, 'Why might a government protect an infant industry?', '[{"text":"To reduce competition for consumers"},{"text":"To give a new domestic industry time to grow and become competitive"},{"text":"To increase imports"},{"text":"To lower prices immediately"}]'::jsonb, 1, 'Temporary protection lets a young industry reach economies of scale before facing full international competition.', 3, 'analyse', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'a191fe60ad5920898a463e0bba67c28a'),
  ('igcse.english', 'reading', 'igcse.english/reading/summary', 'mcq', null, 'The main purpose of a topic sentence is to:', '[{"text":"Conclude the paragraph"},{"text":"Provide a transition"},{"text":"Introduce the paragraph''s main idea"},{"text":"Give evidence"}]'::jsonb, 2, 'A topic sentence states the paragraph''s main idea — usually the first sentence. All other sentences support it.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '844fd8e557f18d96a541361176f2ebe3'),
  ('igcse.english', 'reading', 'igcse.english/reading/inference', 'mcq', null, '''Implicit'' meaning in a text means:', '[{"text":"Directly stated"},{"text":"Hidden or suggested, not stated directly"},{"text":"Repeated throughout"},{"text":"Found in the title"}]'::jsonb, 1, 'Implicit = implied/suggested. Explicit = directly stated. Good readers ''read between the lines'' for implicit meaning.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '9c89812ab8daacf12b75760ddf86f07d'),
  ('igcse.english', 'reading', 'igcse.english/reading/inference', 'mcq', null, 'To infer means to:', '[{"text":"Copy directly"},{"text":"Work out meaning from clues"},{"text":"Skip a section"},{"text":"Count words"}]'::jsonb, 1, 'Inference is reading between the lines using evidence and clues.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '2135df688e20f37b5b4b8d6670786cb2'),
  ('igcse.english', 'reading', 'igcse.english/reading/explicit-meaning', 'mcq', null, 'Skimming a text means reading:', '[{"text":"Every word slowly"},{"text":"Quickly for the general idea"},{"text":"Only the last line"},{"text":"Backwards"}]'::jsonb, 1, 'Skimming = reading fast to get the gist; scanning = hunting for specific info.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '5f6c577f598afcab41b1ede15ee913f1'),
  ('igcse.english', 'reading', 'igcse.english/reading/inference', 'mcq', null, 'The ''tone'' of a passage refers to the writer''s:', '[{"text":"Handwriting"},{"text":"Attitude toward the subject"},{"text":"Word count"},{"text":"Font"}]'::jsonb, 1, 'Tone is the writer''s attitude (e.g. sarcastic, formal, hopeful).', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'c654885498af66b6f41135279db39a21'),
  ('igcse.english', 'reading', 'igcse.english/reading/summary', 'mcq', null, 'A summary should be:', '[{"text":"Longer than the original"},{"text":"A short version of the main points"},{"text":"Word-for-word"},{"text":"Only the title"}]'::jsonb, 1, 'A summary briefly captures the key points in fewer words.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'a7d951cf48b413b11cde57278bc13b99'),
  ('igcse.english', 'writing', 'igcse.english/writing/structure', 'mcq', null, 'A thesis statement is:', '[{"text":"The conclusion of an essay"},{"text":"A supporting detail"},{"text":"A topic sentence"},{"text":"The main argument of the essay"}]'::jsonb, 3, 'The thesis statement is your essay''s central argument or claim — usually at the end of the introduction paragraph.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '61b761b0876d12f5383a87b139418807'),
  ('igcse.english', 'language', 'igcse.english/language/grammar-usage', 'mcq', null, 'Which is an example of the passive voice?', '[{"text":"She writes the report."},{"text":"He ran fast."},{"text":"The report was written by her."},{"text":"They will go home."}]'::jsonb, 2, 'Passive voice: subject receives the action. ''The report was written by her'' — ''report'' is acted upon.', 3, 'recall', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'ad62e9949fa6eb0e0a36b6a3026d9028'),
  ('igcse.english', 'writing', 'igcse.english/writing/argument', 'mcq', null, 'A counter-argument strengthens an essay by:', '[{"text":"Weakening your main point"},{"text":"Adding more evidence"},{"text":"Showing you understand opposing views"},{"text":"Summarising your points"}]'::jsonb, 2, 'Addressing counter-arguments shows critical thinking and strengthens your credibility by acknowledging and refuting opposing views.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '234060a1bb98e3e27ae008047b52e665'),
  ('igcse.english', 'writing', 'igcse.english/writing/audience-purpose', 'mcq', null, 'In academic essays, contractions (e.g., ''don''t'') should:', '[{"text":"Always be used"},{"text":"Sometimes be used"},{"text":"Be avoided — use full forms"},{"text":"Only used in quotations"}]'::jsonb, 2, 'Formal academic essays avoid contractions. Write ''do not'' instead of ''don''t'' for a professional, formal tone.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '16caa978ef9b3215a5c91455d86e6ddd'),
  ('igcse.english', 'writing', 'igcse.english/writing/argument', 'mcq', null, 'An effective introduction should:', '[{"text":"Give every detail"},{"text":"Hook the reader and state the thesis"},{"text":"Only define words"},{"text":"Be one word"}]'::jsonb, 1, 'A good intro grabs attention and presents the main argument (thesis).', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'bb7ecb764cfe5df6eec6cce67c7792ee'),
  ('igcse.english', 'writing', 'igcse.english/writing/structure', 'mcq', null, 'Each body paragraph should focus on:', '[{"text":"Many unrelated ideas"},{"text":"One main idea"},{"text":"Only quotations"},{"text":"The conclusion"}]'::jsonb, 1, 'Strong paragraphs develop a single main idea with evidence and analysis.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '6525d9065b2f11a789c9ff7d99557e2d'),
  ('igcse.english', 'writing', 'igcse.english/writing/structure', 'mcq', null, '''PEEL'' in essay structure stands for Point, Evidence, Explain and:', '[{"text":"Link"},{"text":"List"},{"text":"Logic"},{"text":"Length"}]'::jsonb, 0, 'PEEL: Point, Evidence, Explain, Link — a paragraph framework.', 3, 'analyse', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '98731dea3682b8f29ba8781d8aa798fd'),
  ('igcse.english', 'writing', 'igcse.english/writing/argument', 'mcq', null, 'A conclusion should:', '[{"text":"Introduce new evidence"},{"text":"Summarise and reinforce the argument"},{"text":"Start a new topic"},{"text":"Quote a dictionary"}]'::jsonb, 1, 'Conclusions restate the thesis and draw the argument together — no new evidence.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '66d24d741aa948451f8e9fe125073ebb'),
  ('igcse.english', 'writing', 'igcse.english/writing/structure', 'mcq', null, 'Formal academic writing avoids:', '[{"text":"Topic sentences"},{"text":"Slang and contractions"},{"text":"Evidence"},{"text":"Paragraphs"}]'::jsonb, 1, 'Formal writing avoids slang, contractions, and overly casual tone.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'cc56685d9bc9b025c2b508a1728ac821'),
  ('igcse.english', 'writing', 'igcse.english/writing/structure', 'mcq', null, 'A topic sentence usually appears:', '[{"text":"At the end of the essay"},{"text":"At the start of a paragraph"},{"text":"Only in the title"},{"text":"Never"}]'::jsonb, 1, 'The topic sentence opens a paragraph and signals its main idea.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'da90869d660057b1f8da5ab410223af6'),
  ('igcse.english', 'language', 'igcse.english/language/punctuation', 'mcq', null, 'The apostrophe in ''it''s'' indicates:', '[{"text":"Possessive form"},{"text":"Plural form"},{"text":"''It is'' (contraction)"},{"text":"Emphasis"}]'::jsonb, 2, 'It''s = it is (contraction). Its (no apostrophe) = possessive. Common error: confusing the two.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'adaa5c4babb1c7a8de9fffe9489027df'),
  ('igcse.english', 'language', 'igcse.english/language/grammar-usage', 'mcq', null, '''Neither...nor'' takes a verb that agrees with:', '[{"text":"Always plural verb"},{"text":"Always singular verb"},{"text":"The nearest subject"},{"text":"Both subjects"}]'::jsonb, 2, 'With ''neither...nor'', the verb agrees with the nearest subject. ''Neither she nor they are going'' — ''they'' is nearest.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'b804eee560fdc868e31ee2784fa65b34'),
  ('igcse.english', 'language', 'igcse.english/language/sentence-structure', 'mcq', null, 'Which word is a conjunction?', '[{"text":"Quickly"},{"text":"And"},{"text":"Happy"},{"text":"Run"}]'::jsonb, 1, '''And'' joins words or clauses — it is a conjunction.', 2, 'recall', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '296587d86313a018efba74b93f0bddaa'),
  ('igcse.english', 'language', 'igcse.english/language/punctuation', 'mcq', null, 'Which sentence is punctuated correctly?', '[{"text":"Its raining today."},{"text":"It''s raining today."},{"text":"Its'' raining today."},{"text":"Its raining, today"}]'::jsonb, 1, '''It''s'' = ''it is''. ''Its'' (no apostrophe) is possessive.', 3, 'recall', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'a9d594b6db0b92bd098cf3754003879f'),
  ('igcse.english', 'language', 'igcse.english/language/grammar-usage', 'mcq', null, 'Choose the correct word: ''The team played ___ best.''', '[{"text":"they''re"},{"text":"their"},{"text":"there"},{"text":"theyre"}]'::jsonb, 1, '''Their'' shows possession (the team''s best).', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '1c9d6cac06c477aff82d51777e4491ea'),
  ('igcse.english', 'language', 'igcse.english/language/grammar-usage', 'mcq', null, 'An adverb usually describes a:', '[{"text":"Noun"},{"text":"Verb"},{"text":"Pronoun"},{"text":"Conjunction"}]'::jsonb, 1, 'Adverbs modify verbs (and adjectives/other adverbs), often ending in -ly.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '4314ba9cb7802596fc208661e58b13b6'),
  ('igcse.english', 'language', 'igcse.english/language/grammar-usage', 'mcq', null, 'Which is a complete sentence?', '[{"text":"Running down the street."},{"text":"Because she was late."},{"text":"The dog barked."},{"text":"After the rain stopped."}]'::jsonb, 2, '''The dog barked'' has a subject and a verb and expresses a complete thought.', 3, 'recall', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '21262d8f58cca8c21bea20fccebdf95b'),
  ('igcse.english', 'language', 'igcse.english/language/grammar-usage', 'mcq', null, 'Past tense of ''to go'' is:', '[{"text":"Goed"},{"text":"Went"},{"text":"Gone"},{"text":"Going"}]'::jsonb, 1, '''Went'' is the simple past; ''gone'' is the past participle (has gone).', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '5b1968ca8b7339a7a6f6c0019644de31'),
  ('igcse.english', 'techniques', 'igcse.english/techniques/narrative-perspective', 'mcq', null, 'A soliloquy is when a character:', '[{"text":"Has a conversation with another"},{"text":"Gives a speech to a crowd"},{"text":"Speaks their thoughts aloud alone on stage"},{"text":"Reads a letter"}]'::jsonb, 2, 'A soliloquy is a dramatic device where a character speaks their internal thoughts aloud, usually alone on stage. Romeo''s balcony scene.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '22a2ce78344f621091e99c9029a9bebe'),
  ('igcse.english', 'techniques', 'igcse.english/techniques/figurative', 'mcq', null, 'A simile uses:', '[{"text":"Direct comparison (is/are)"},{"text":"Exaggeration"},{"text":"''Like'' or ''as'' for comparison"},{"text":"Human qualities for objects"}]'::jsonb, 2, 'Simile = comparison using ''like'' or ''as''. ''Her smile was like sunshine.'' Metaphor = direct comparison without like/as.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'e9685dcf0e36af74bdfe3e77081c6331'),
  ('igcse.english', 'techniques', 'igcse.english/techniques/tone-mood', 'mcq', null, 'Dramatic irony occurs when:', '[{"text":"A character makes a dramatic speech"},{"text":"The audience knows something a character doesn''t"},{"text":"A character knows more than the audience"},{"text":"There is an unexpected twist"}]'::jsonb, 1, 'Dramatic irony: the audience possesses knowledge that a character lacks, creating tension or humour.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'b5302abb0eeefe7cf7a34e455045b93a'),
  ('igcse.english', 'techniques', 'igcse.english/techniques/figurative', 'mcq', null, 'Personification gives human qualities to:', '[{"text":"People"},{"text":"Non-human things"},{"text":"Numbers"},{"text":"Verbs"}]'::jsonb, 1, 'Personification describes objects/ideas as if they were human (''the wind whispered'').', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'db98a5eaf71c580fcd32eefdef3c118b'),
  ('igcse.english', 'techniques', 'igcse.english/techniques/figurative', 'mcq', null, 'A metaphor differs from a simile because it:', '[{"text":"Uses ''like'' or ''as''"},{"text":"States one thing IS another"},{"text":"Rhymes"},{"text":"Is always short"}]'::jsonb, 1, 'A metaphor says X is Y directly (''time is a thief''); a simile uses like/as.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'd9fb9e43ea29bab6320ca2b6b09c74ae'),
  ('igcse.english', 'techniques', 'igcse.english/techniques/tone-mood', 'mcq', null, 'The mood of a text is its:', '[{"text":"Word count"},{"text":"Emotional atmosphere"},{"text":"Author''s name"},{"text":"Page length"}]'::jsonb, 1, 'Mood is the feeling/atmosphere a text creates in the reader.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'b17e06764552ac6007d331c3308556c9'),
  ('igcse.english', 'techniques', 'igcse.english/techniques/sound-devices', 'mcq', null, 'Alliteration is the repetition of:', '[{"text":"Whole words"},{"text":"Initial consonant sounds"},{"text":"Rhymes only"},{"text":"Punctuation"}]'::jsonb, 1, 'Alliteration repeats initial consonant sounds (''slippery snake'').', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '4575a895f6c0b76709abdf9bff7a6afb'),
  ('igcse.english', 'techniques', 'igcse.english/techniques/narrative-perspective', 'mcq', null, 'A protagonist is the:', '[{"text":"Villain"},{"text":"Main character"},{"text":"Setting"},{"text":"Narrator''s pet"}]'::jsonb, 1, 'The protagonist is the central character; the antagonist opposes them.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '73e6c574a3dc77f99dd8b8e838603a39'),
  ('igcse.english', 'techniques', 'igcse.english/techniques/tone-mood', 'mcq', null, 'A theme is the:', '[{"text":"First sentence"},{"text":"Central message or idea"},{"text":"Author''s age"},{"text":"Book cover"}]'::jsonb, 1, 'A theme is the underlying message or central idea of a work.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '317453a5d437cd2fe93bcbb7a871fd0e'),
  ('igcse.business', 'enterprise', 'igcse.business/enterprise/entrepreneurs', 'mcq', null, 'A person who starts and runs a business, taking on risk, is an:', '[{"text":"Employee"},{"text":"Entrepreneur"},{"text":"Accountant"},{"text":"Investor"}]'::jsonb, 1, 'An entrepreneur starts a venture and bears its financial risk.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '59c28cc99492e2e828a41d656178c016'),
  ('igcse.business', 'enterprise', 'igcse.business/enterprise/ownership', 'mcq', null, 'A business owned by one person is a:', '[{"text":"Partnership"},{"text":"Sole trader"},{"text":"Corporation"},{"text":"Cooperative"}]'::jsonb, 1, 'A sole trader (sole proprietorship) is owned and run by one individual.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'ba0ced8bfbaf942163d1ef13487c587b'),
  ('igcse.business', 'enterprise', 'igcse.business/enterprise/ownership', 'mcq', null, 'Which is an advantage of a private limited company over a sole trader?', '[{"text":"The owner keeps all profits"},{"text":"Shareholders have limited liability"},{"text":"Accounts are kept private and never published"},{"text":"It is simpler to set up"}]'::jsonb, 1, 'Shareholders can only lose what they invested; sole traders have unlimited liability.', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '63c82e24d44949c878f992a551f44c21'),
  ('igcse.business', 'enterprise', 'igcse.business/enterprise/sectors', 'mcq', null, 'Which sector of industry does a car manufacturer belong to?', '[{"text":"Primary"},{"text":"Secondary"},{"text":"Tertiary"},{"text":"Public"}]'::jsonb, 1, 'The secondary sector turns raw materials into finished goods; primary extracts resources, tertiary provides services.', 2, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'bd0c4944b50850fa3b1a8de21a0d9bd1'),
  ('igcse.business', 'enterprise', 'igcse.business/enterprise/entrepreneurs', 'mcq', null, 'What is meant by "added value"?', '[{"text":"The profit after tax"},{"text":"The difference between the selling price and the cost of bought-in materials"},{"text":"The total revenue of the business"},{"text":"The amount of tax added to a price"}]'::jsonb, 1, 'Added value is created by processing or branding: selling price minus the cost of inputs bought in.', 3, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '2d2a404655789682d3009dd69c31ed2e'),
  ('igcse.business', 'enterprise', 'igcse.business/enterprise/stakeholders', 'mcq', null, 'Which is a stakeholder but not an owner of a business?', '[{"text":"A shareholder"},{"text":"A sole trader"},{"text":"An employee"},{"text":"A partner"}]'::jsonb, 2, 'Employees have an interest in the business (pay, job security) without owning it.', 2, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '7c94db7959538022032e9a2d646b6674'),
  ('igcse.business', 'enterprise', 'igcse.business/enterprise/ownership', 'mcq', null, 'A franchise allows a business to:', '[{"text":"Sell its own shares on the stock exchange"},{"text":"Trade using another firm’s brand and business model in return for fees"},{"text":"Avoid all taxes"},{"text":"Merge with a competitor"}]'::jsonb, 1, 'The franchisee pays the franchisor for the right to use its name, products and methods.', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '892e8bcc387b86202abc7c5ba82236af'),
  ('igcse.business', 'enterprise', 'igcse.business/enterprise/ownership', 'mcq', null, 'Why do many new businesses fail?', '[{"text":"Too many customers"},{"text":"Poor cash flow management and lack of market research"},{"text":"Having limited liability"},{"text":"Too much profit"}]'::jsonb, 1, 'Running out of cash and misjudging demand are among the most common reasons for failure.', 2, 'analyse', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '2fc0435d698d9307441d6d5bb30850f7'),
  ('igcse.business', 'enterprise', 'igcse.business/enterprise/growth', 'mcq', null, 'Which is an example of a merger that is a horizontal integration?', '[{"text":"A car maker buying a tyre supplier"},{"text":"Two supermarket chains joining together"},{"text":"A farm buying a chain of shops"},{"text":"A bank buying a football club"}]'::jsonb, 1, 'Horizontal integration joins firms at the same stage of production in the same industry.', 3, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'b472eab0f953755d06451ffc75343666'),
  ('igcse.business', 'marketing', 'igcse.business/marketing/segmentation', 'mcq', null, 'The ''target market'' refers to:', '[{"text":"All people everywhere"},{"text":"The specific group a product is aimed at"},{"text":"The factory"},{"text":"The competitors"}]'::jsonb, 1, 'A target market is the specific customer group a business aims to serve.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '6e003159a21a025841783029a3aa2535'),
  ('igcse.business', 'marketing', 'igcse.business/marketing/marketing-mix', 'mcq', null, 'Which is one of the classic ''4 Ps'' of marketing?', '[{"text":"Profit"},{"text":"Price"},{"text":"People"},{"text":"Polish"}]'::jsonb, 1, 'The 4 Ps are Product, Price, Place, and Promotion.', 3, 'recall', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'b9ac0ba84fc8026f443497e97f385260'),
  ('igcse.business', 'marketing', 'igcse.business/marketing/marketing-mix', 'mcq', null, 'Building a recognizable name and image is called:', '[{"text":"Branding"},{"text":"Auditing"},{"text":"Importing"},{"text":"Hedging"}]'::jsonb, 0, 'Branding creates a distinct identity for a product or company.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'cea2c31ce99aa17c50018f6f4b89ba36'),
  ('igcse.business', 'marketing', 'igcse.business/marketing/marketing-mix', 'mcq', null, 'What is market segmentation?', '[{"text":"Selling in every country"},{"text":"Dividing a market into groups of customers with similar characteristics"},{"text":"Setting the lowest price"},{"text":"Advertising on television"}]'::jsonb, 1, 'Segments (by age, income, location, lifestyle) let a business target products and promotion precisely.', 2, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'a47cea436bb593d14483555de87cc8ca'),
  ('igcse.business', 'marketing', 'igcse.business/marketing/pricing', 'mcq', null, 'A business sets a low price to enter a market and gain market share quickly. This is:', '[{"text":"Price skimming"},{"text":"Penetration pricing"},{"text":"Cost-plus pricing"},{"text":"Competitive pricing"}]'::jsonb, 1, 'Penetration pricing starts low to attract customers; skimming starts high for new, innovative products.', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '8f242fc991438793ccade9dcb20a48ec'),
  ('igcse.business', 'marketing', 'igcse.business/marketing/market-research', 'mcq', null, 'Which is an example of primary market research?', '[{"text":"Reading government statistics"},{"text":"Conducting a customer survey"},{"text":"Using a newspaper report"},{"text":"Checking a competitor’s website"}]'::jsonb, 1, 'Primary research collects new, first-hand data; the others use existing (secondary) data.', 2, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'ae610d5d8f511597cedc1d43b467a2c2'),
  ('igcse.business', 'marketing', 'igcse.business/marketing/product-life-cycle', 'mcq', null, 'In which stage of the product life cycle are sales growing fastest?', '[{"text":"Introduction"},{"text":"Growth"},{"text":"Maturity"},{"text":"Decline"}]'::jsonb, 1, 'During growth, awareness spreads and sales rise rapidly; in maturity sales level off.', 2, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '798875e827f71c3be8c13df341533b17'),
  ('igcse.business', 'marketing', 'igcse.business/marketing/product-life-cycle', 'mcq', null, 'An extension strategy is used to:', '[{"text":"Launch a completely new product"},{"text":"Lengthen the life of a product before it declines"},{"text":"Close a business"},{"text":"Reduce the number of employees"}]'::jsonb, 1, 'New features, packaging or markets can extend a product’s maturity stage.', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '44961351e079d72316e5c561517434b1'),
  ('igcse.business', 'marketing', 'igcse.business/marketing/marketing-mix', 'mcq', null, 'Which is a benefit of selling online (e-commerce) for a business?', '[{"text":"Customers can always touch the product"},{"text":"Access to a wider, even global, market at lower cost"},{"text":"No delivery costs"},{"text":"No competition"}]'::jsonb, 1, 'Online sales reach customers beyond a physical location, often with lower premises costs.', 2, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '4406a9b95c4e4dce8e67a196303bab88'),
  ('igcse.business', 'operations', 'igcse.business/operations/productivity-quality', 'mcq', null, 'Quality control is mainly about:', '[{"text":"Advertising"},{"text":"Ensuring products meet standards"},{"text":"Hiring staff"},{"text":"Setting prices"}]'::jsonb, 1, 'Quality control checks that products meet defined standards.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '44004d632df31c67488d087371e0270f'),
  ('igcse.business', 'operations', 'igcse.business/operations/production-methods', 'mcq', null, 'Batch production is best described as:', '[{"text":"Making one unique product at a time"},{"text":"Making a group of identical products before switching to another group"},{"text":"Continuous production of identical products"},{"text":"Producing only when an order is received"}]'::jsonb, 1, 'Batch production makes a set quantity of one item, then the equipment is reset for the next batch (e.g. a bakery).', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'f45f05b0dec2b8dc655bee0100954f16'),
  ('igcse.business', 'operations', 'igcse.business/operations/inventory-lean', 'mcq', null, 'What is the main aim of just-in-time (JIT) inventory management?', '[{"text":"To hold large buffer stocks"},{"text":"To minimise stock by receiving materials only when needed"},{"text":"To increase warehouse space"},{"text":"To buy in bulk to get discounts"}]'::jsonb, 1, 'JIT cuts storage costs and waste, but depends on reliable suppliers.', 3, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'd6ea68fa5d335fdd170048c09dabc0f7'),
  ('igcse.business', 'operations', 'igcse.business/operations/productivity-quality', 'mcq', null, 'Productivity is measured as:', '[{"text":"Total output ÷ number of workers (or inputs)"},{"text":"Total revenue ÷ total costs"},{"text":"Profit ÷ capital"},{"text":"Number of workers ÷ output"}]'::jsonb, 0, 'Labour productivity = output per worker over a period.', 2, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '3902b6906cbfd9bc93362022373ffc0d'),
  ('igcse.business', 'operations', 'igcse.business/operations/break-even', 'mcq', null, 'A firm’s fixed costs are $20 000, selling price $15 and variable cost $10 per unit. What is the break-even output?', '[{"text":"800 units"},{"text":"1 333 units"},{"text":"2 000 units"},{"text":"4 000 units"}]'::jsonb, 3, 'Contribution per unit = $15 − $10 = $5. Break-even = $20 000 ÷ $5 = 4 000 units.', 4, 'apply', 'extended', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '64dd3574cb445989b04818ab0b462a39'),
  ('igcse.business', 'operations', 'igcse.business/operations/scale', 'mcq', null, 'Which is an example of a diseconomy of scale?', '[{"text":"Bulk-buying discounts"},{"text":"Communication problems as the business becomes very large"},{"text":"Cheaper finance from banks"},{"text":"Spreading advertising costs"}]'::jsonb, 1, 'Very large firms can suffer slow communication and poor coordination, raising average costs.', 3, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'cd14a2220d13663e0123ec3148583228'),
  ('igcse.business', 'operations', 'igcse.business/operations/productivity-quality', 'mcq', null, 'Total quality management (TQM) means that:', '[{"text":"Only inspectors are responsible for quality"},{"text":"Every employee is responsible for quality at every stage"},{"text":"Quality is checked only at the end"},{"text":"Products are never tested"}]'::jsonb, 1, 'TQM builds a culture where all staff aim for zero defects throughout production.', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '378aa79b454f8b480cbc3c596a9e0046'),
  ('igcse.business', 'finance', 'igcse.business/finance/profit-margins', 'mcq', null, 'Revenue minus costs equals:', '[{"text":"Profit"},{"text":"Tax"},{"text":"Equity"},{"text":"Debt"}]'::jsonb, 0, 'Profit = revenue − costs. It''s what remains after expenses.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '30a6a4498e028d8043071a15fc4bd8f3'),
  ('igcse.business', 'finance', 'igcse.business/finance/accounts-ratios', 'mcq', null, 'Money a business owes to others is its:', '[{"text":"Asset"},{"text":"Liability"},{"text":"Revenue"},{"text":"Profit"}]'::jsonb, 1, 'A liability is a debt or obligation the business owes.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'f3f52d0f022ce5865de2284be1e97950'),
  ('igcse.business', 'finance', 'igcse.business/finance/cash-flow', 'mcq', null, 'Cash flow refers to:', '[{"text":"Total profit"},{"text":"Money moving in and out of a business"},{"text":"The number of staff"},{"text":"The brand value"}]'::jsonb, 1, 'Cash flow is the movement of money into and out of a business over time.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '4225083019fa6f9bdafe98cd536075a0'),
  ('igcse.business', 'finance', 'igcse.business/finance/profit-margins', 'mcq', null, 'A business has revenue of $50 000 and cost of sales of $30 000. What is its gross profit margin?', '[{"text":"40%"},{"text":"60%"},{"text":"20%"},{"text":"66.7%"}]'::jsonb, 0, 'Gross profit = $20 000. Margin = 20 000 ÷ 50 000 × 100 = 40%.', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '351509707aa672cd52bc6913abae820a'),
  ('igcse.business', 'finance', 'igcse.business/finance/sources-of-finance', 'mcq', null, 'Which is a current asset?', '[{"text":"Machinery"},{"text":"Buildings"},{"text":"Inventory (stock)"},{"text":"A long-term bank loan"}]'::jsonb, 2, 'Current assets are expected to be turned into cash within a year: inventory, receivables, cash.', 2, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'e55dd2cdb4a95775c06c8cbec4cc55ae'),
  ('igcse.business', 'finance', 'igcse.business/finance/cash-flow', 'mcq', null, 'What does a cash-flow forecast show?', '[{"text":"The value of the business"},{"text":"Expected cash inflows and outflows over future months"},{"text":"Profit for the last year"},{"text":"The number of shares issued"}]'::jsonb, 1, 'It predicts when cash will come in and go out, helping avoid running out of cash.', 2, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '07a994fbc242754695ff288a9999d0dc'),
  ('igcse.business', 'finance', 'igcse.business/finance/accounts-ratios', 'mcq', null, 'The current ratio is calculated as:', '[{"text":"Current assets ÷ current liabilities"},{"text":"Current liabilities ÷ current assets"},{"text":"Profit ÷ revenue"},{"text":"Revenue ÷ current assets"}]'::jsonb, 0, 'Current ratio measures liquidity; a value around 1.5–2 is often considered comfortable.', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '4d73bd1e139581bdee6180a5e3d500be'),
  ('igcse.business', 'finance', 'igcse.business/finance/sources-of-finance', 'mcq', null, 'Which is an internal source of finance?', '[{"text":"A bank loan"},{"text":"Retained profit"},{"text":"Issuing new shares"},{"text":"A government grant"}]'::jsonb, 1, 'Retained profit comes from within the business and has no interest cost.', 2, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '16a6f41df2c8a15c7e41438074286134'),
  ('igcse.business', 'finance', 'igcse.business/finance/cash-flow', 'mcq', null, 'Why can a profitable business still fail?', '[{"text":"Because profit is always zero"},{"text":"Because it may run out of cash to pay its debts on time"},{"text":"Because it has too many assets"},{"text":"Because customers pay immediately"}]'::jsonb, 1, 'Profit is not cash: if customers pay late while bills are due, the business can become insolvent.', 3, 'analyse', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '0371287fd081dfd4fd3baee71a8586c7'),
  ('sat.math', 'algebra', 'sat.math/algebra/linear-equations', 'mcq', null, 'If 3x − 7 = 2x + 5, what is the value of x?', '[{"text":"−12"},{"text":"−2"},{"text":"2"},{"text":"12"}]'::jsonb, 3, 'Subtract 2x from both sides: x − 7 = 5, so x = 12.', 2, 'apply', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '1269babdf9cd2d6b1caa28d32bcf6a85'),
  ('sat.math', 'algebra', 'sat.math/algebra/linear-functions', 'mcq', null, 'A gym charges a $40 joining fee plus $25 per month. Which expression gives the total cost, in dollars, for m months?', '[{"text":"40m + 25"},{"text":"25m + 40"},{"text":"65m"},{"text":"(40 + 25)m"}]'::jsonb, 1, 'The monthly charge scales with m (25m); the joining fee is paid once (+40).', 2, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '3a44a6a339cf1e904529cba78ec3d7c9'),
  ('sat.math', 'algebra', 'sat.math/algebra/linear-functions', 'mcq', null, 'The line y = −2x + 6 crosses the x-axis at which point?', '[{"text":"(0, 6)"},{"text":"(3, 0)"},{"text":"(−3, 0)"},{"text":"(6, 0)"}]'::jsonb, 1, 'On the x-axis y = 0: 0 = −2x + 6, so x = 3.', 2, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '5586a8a4de2a4db9b7a0074906b5edab'),
  ('sat.math', 'algebra', 'sat.math/algebra/linear-functions', 'mcq', null, 'Which line is parallel to y = 4x − 1 and passes through (0, 3)?', '[{"text":"y = −4x + 3"},{"text":"y = 4x + 3"},{"text":"y = ¼x + 3"},{"text":"y = 3x + 4"}]'::jsonb, 1, 'Parallel lines share a slope (4); the y-intercept is 3.', 3, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '0c10b71a8d0a4703c4d2e81e1848c332'),
  ('sat.math', 'algebra', 'sat.math/algebra/systems', 'mcq', null, 'If 2x + y = 11 and x − y = 1, what is the value of x?', '[{"text":"3"},{"text":"4"},{"text":"5"},{"text":"6"}]'::jsonb, 1, 'Add the equations: 3x = 12, so x = 4 (and y = 3).', 3, 'apply', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '1ef886df39004896ebe77055fb95cfd0'),
  ('sat.math', 'algebra', 'sat.math/algebra/inequalities', 'mcq', null, 'Which value of x satisfies 5 − 2x > 11?', '[{"text":"−4"},{"text":"−3"},{"text":"0"},{"text":"3"}]'::jsonb, 0, '−2x > 6 gives x < −3 (the inequality flips when dividing by −2). Only −4 is less than −3.', 3, 'apply', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'e3af10dd91e766c8e9ce6aeb89c8d28d'),
  ('sat.math', 'algebra', 'sat.math/algebra/systems', 'mcq', null, 'The system 3x + ky = 7 and 6x + 8y = 14 has infinitely many solutions. What is k?', '[{"text":"2"},{"text":"4"},{"text":"8"},{"text":"16"}]'::jsonb, 1, 'The second equation is 2 × the first if 2k = 8, so k = 4.', 4, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '8fd229517a39e002aab7ef3d1ef63779'),
  ('sat.math', 'algebra', 'sat.math/algebra/linear-functions', 'mcq', null, 'A plumber charges a fixed fee plus an hourly rate. A 2-hour job costs $150 and a 5-hour job costs $285. What is the hourly rate?', '[{"text":"$45"},{"text":"$57"},{"text":"$60"},{"text":"$75"}]'::jsonb, 0, 'Three extra hours cost $285 − $150 = $135, so the rate is $135 ÷ 3 = $45.', 3, 'apply', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '3c1fd90fa81e088365b14cb021633b35'),
  ('sat.math', 'algebra', 'sat.math/algebra/linear-equations', 'mcq', null, 'For what value of c does the equation 4(x − c) = 4x − 12 have infinitely many solutions?', '[{"text":"−3"},{"text":"3"},{"text":"4"},{"text":"12"}]'::jsonb, 1, '4x − 4c = 4x − 12 for all x when 4c = 12, so c = 3.', 4, 'apply', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '649b07a0f99b09848f811ce87b228cc4'),
  ('sat.math', 'algebra', null, 'mcq', null, 'Solve: x² − 5x + 6 = 0', '[{"text":"x = 1 and 6"},{"text":"x = 2 and 3"},{"text":"x = −2 and −3"},{"text":"x = −1 and −6"}]'::jsonb, 1, 'Factorise: (x−2)(x−3) = 0. So x = 2 or x = 3. Check: 2²−5(2)+6 = 0 ✓', 3, 'apply', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'pending_review', 'Imported from the original Chapter app. No skill match: check topic and syllabus fit before publishing.', 'cebd5f6e7806270371c4ea3d8b4c4a12'),
  ('sat.math', 'algebra', null, 'mcq', null, 'Solve: 2x + 3 = 11', '[{"text":"x = 7"},{"text":"x = 5.5"},{"text":"x = 4"},{"text":"x = 3"}]'::jsonb, 2, '2x = 11 − 3 = 8. x = 8/2 = 4', 2, 'apply', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'pending_review', 'Imported from the original Chapter app. No skill match: check topic and syllabus fit before publishing.', '78aad6d2e6349240675c8d2796b146b8'),
  ('sat.math', 'advanced-math', 'sat.math/advanced-math/expressions', 'mcq', null, 'Simplify: (x²y³) ÷ (xy)', '[{"text":"xy²"},{"text":"x²y²"},{"text":"xy"},{"text":"x²y"}]'::jsonb, 0, 'x²y³ / xy = x^(2-1) · y^(3-1) = xy²', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'f0c833e0f1fef56608d6f0e8d688090c'),
  ('sat.math', 'algebra', null, 'mcq', null, 'The sum 1 + 2 + 3 + ... + 100 equals:', '[{"text":"5000"},{"text":"4950"},{"text":"5050"},{"text":"5100"}]'::jsonb, 2, 'Using Gauss formula: n(n+1)/2 = 100 × 101 / 2 = 5050', 4, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'pending_review', 'Imported from the original Chapter app. No skill match: check topic and syllabus fit before publishing.', '344f5a6ae2b2830351dc44a6ee752457'),
  ('sat.math', 'algebra', null, 'mcq', null, 'If f(x) = 2x² − 3, what is f(3)?', '[{"text":"12"},{"text":"9"},{"text":"15"},{"text":"18"}]'::jsonb, 2, 'f(3) = 2(3)² − 3 = 2(9) − 3 = 18 − 3 = 15', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'pending_review', 'Imported from the original Chapter app. No skill match: check topic and syllabus fit before publishing.', 'cea8c9d46801f6777717bae86ef4b6fe'),
  ('sat.math', 'advanced-math', 'sat.math/advanced-math/quadratics', 'mcq', null, 'What are the solutions of x² − 5x − 14 = 0?', '[{"text":"x = 7 and x = −2"},{"text":"x = −7 and x = 2"},{"text":"x = 14 and x = −1"},{"text":"x = 5 and x = −14"}]'::jsonb, 0, 'Factor: (x − 7)(x + 2) = 0, so x = 7 or x = −2.', 2, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'fe79cd9c0ec2f22854c538c40e134c75'),
  ('sat.math', 'advanced-math', 'sat.math/advanced-math/functions', 'mcq', null, 'If f(x) = 2x² − 3x + 1, what is f(−2)?', '[{"text":"3"},{"text":"11"},{"text":"15"},{"text":"−1"}]'::jsonb, 2, 'f(−2) = 2(4) − 3(−2) + 1 = 8 + 6 + 1 = 15.', 2, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '6de443552e517fb0793a4a5cfc1f695e'),
  ('sat.math', 'advanced-math', 'sat.math/advanced-math/expressions', 'mcq', null, 'Which expression is equivalent to (x + 3)² − (x − 3)²?', '[{"text":"0"},{"text":"18"},{"text":"12x"},{"text":"2x² + 18"}]'::jsonb, 2, 'Difference of squares: [(x + 3) − (x − 3)][(x + 3) + (x − 3)] = 6 × 2x = 12x.', 3, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'f882239452a24a632421e521e3e15286'),
  ('sat.math', 'advanced-math', 'sat.math/advanced-math/functions', 'mcq', null, 'The function f(x) = 500(0.9)ˣ models the value of a machine after x years. What does 0.9 represent?', '[{"text":"The value decreases by 90% each year"},{"text":"The value decreases by 10% each year"},{"text":"The initial value is $0.90"},{"text":"The value increases by 9% each year"}]'::jsonb, 1, 'Multiplying by 0.9 each year keeps 90% of the value, a 10% decrease.', 3, 'apply', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '4b02e6b62563cf17255827042996604d'),
  ('sat.math', 'advanced-math', 'sat.math/advanced-math/quadratics', 'mcq', null, 'The vertex of the parabola y = (x − 4)² + 1 is:', '[{"text":"(−4, 1)"},{"text":"(4, 1)"},{"text":"(4, −1)"},{"text":"(1, 4)"}]'::jsonb, 1, 'In vertex form y = (x − h)² + k the vertex is (h, k) = (4, 1).', 2, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '6ed07817d44fd06fe4cfc7dcdc3792b9'),
  ('sat.math', 'advanced-math', 'sat.math/advanced-math/quadratics', 'mcq', null, 'How many real solutions does x² + 4x + 7 = 0 have?', '[{"text":"0"},{"text":"1"},{"text":"2"},{"text":"Infinitely many"}]'::jsonb, 0, 'The discriminant b² − 4ac = 16 − 28 = −12 < 0, so there are no real solutions.', 3, 'apply', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '9dd5c4cd60e71c86c4ecaedfef847196'),
  ('sat.math', 'advanced-math', 'sat.math/advanced-math/quadratics', 'mcq', null, 'If x > 0 and x² = 3x + 10, what is x?', '[{"text":"2"},{"text":"5"},{"text":"10"},{"text":"13"}]'::jsonb, 1, 'x² − 3x − 10 = 0 → (x − 5)(x + 2) = 0. Since x > 0, x = 5.', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '3f74bd756e8a3a24cc7da71b82e5627d'),
  ('sat.math', 'advanced-math', 'sat.math/advanced-math/expressions', 'mcq', null, 'Which is equivalent to (x^(3/2))²?', '[{"text":"x^(3/4)"},{"text":"x^(7/2)"},{"text":"x³"},{"text":"x^(5/2)"}]'::jsonb, 2, 'Multiply the exponents: (3/2) × 2 = 3.', 3, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'b91f2b84a4246ead44910507dbcb13a1'),
  ('sat.math', 'advanced-math', 'sat.math/advanced-math/functions', 'mcq', null, 'The graph of y = f(x) is shifted 3 units right. Which equation describes the new graph?', '[{"text":"y = f(x) + 3"},{"text":"y = f(x) − 3"},{"text":"y = f(x − 3)"},{"text":"y = f(x + 3)"}]'::jsonb, 2, 'Replacing x with (x − 3) moves every point 3 units to the right.', 4, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '39f0c75b17740502f8880f2f2ea0b6cf'),
  ('sat.math', 'problem-solving', 'sat.math/problem-solving/ratios-rates', 'mcq', null, 'A recipe uses 3 cups of flour for every 2 cups of sugar. How many cups of flour are needed with 7 cups of sugar?', '[{"text":"4⅔"},{"text":"9"},{"text":"10.5"},{"text":"14"}]'::jsonb, 2, 'Flour : sugar = 3 : 2, so flour = 7 × 3/2 = 10.5 cups.', 2, 'apply', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '1c8efac8ab5d8402a5ed68e055555bfc'),
  ('sat.math', 'problem-solving', 'sat.math/problem-solving/ratios-rates', 'mcq', null, 'A shirt costs $36 after a 25% discount. What was the original price?', '[{"text":"$27"},{"text":"$45"},{"text":"$48"},{"text":"$61"}]'::jsonb, 2, '$36 is 75% of the original: 36 ÷ 0.75 = $48.', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'ec08e86dbcce26108dddf4e9b2a1fc26'),
  ('sat.math', 'problem-solving', 'sat.math/problem-solving/statistics', 'mcq', null, 'The mean of five numbers is 12. Four of the numbers are 8, 10, 13 and 15. What is the fifth number?', '[{"text":"10"},{"text":"12"},{"text":"14"},{"text":"60"}]'::jsonb, 2, 'The total is 5 × 12 = 60; 60 − (8 + 10 + 13 + 15) = 14.', 2, 'apply', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '9f8e28b4d6aaada6c7b3c26dbda2d570'),
  ('sat.math', 'problem-solving', 'sat.math/problem-solving/statistics', 'mcq', null, 'A data set is {4, 7, 7, 9, 23}. If 23 is removed, which statement is true?', '[{"text":"The mean decreases more than the median"},{"text":"The median decreases more than the mean"},{"text":"Both stay the same"},{"text":"The mean increases"}]'::jsonb, 0, 'The mean falls from 10 to 6.75; the median falls from 7 to 7. Outliers affect the mean far more than the median.', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'b21d47e945564ba77ea3c8ab8197b8b0'),
  ('sat.math', 'problem-solving', 'sat.math/problem-solving/ratios-rates', 'mcq', null, 'A car travels 150 miles in 2.5 hours. At the same rate, how far does it travel in 4 hours?', '[{"text":"200 miles"},{"text":"225 miles"},{"text":"240 miles"},{"text":"375 miles"}]'::jsonb, 2, 'Speed = 150 ÷ 2.5 = 60 mph; 60 × 4 = 240 miles.', 2, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '4f089c143f635653a0fd4e5a0f113b04'),
  ('sat.math', 'problem-solving', 'sat.math/problem-solving/sampling-inference', 'mcq', null, 'In a survey of 400 randomly chosen students, 88 said they cycle to school. Based on this, about how many of the school’s 2 500 students cycle?', '[{"text":"220"},{"text":"350"},{"text":"550"},{"text":"880"}]'::jsonb, 2, '88/400 = 22%; 22% of 2 500 = 550.', 3, 'apply', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '420f3d6b4f47d6832d45c55787bcd966'),
  ('sat.math', 'problem-solving', 'sat.math/problem-solving/probability', 'mcq', null, 'A bag has 5 red and 7 blue marbles. Two are drawn without replacement. What is the probability both are red?', '[{"text":"25/144"},{"text":"5/33"},{"text":"5/36"},{"text":"1/6"}]'::jsonb, 1, '(5/12) × (4/11) = 20/132 = 5/33.', 4, 'apply', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'c5c8f14466899a54f669b06efb62a381'),
  ('sat.math', 'problem-solving', 'sat.math/problem-solving/ratios-rates', 'mcq', null, 'A population of 2 000 bacteria doubles every 3 hours. How many are there after 12 hours?', '[{"text":"8 000"},{"text":"16 000"},{"text":"24 000"},{"text":"32 000"}]'::jsonb, 3, '12 hours is 4 doubling periods: 2 000 × 2⁴ = 32 000.', 3, 'apply', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'dae9010d88bbd8424051f803faacbd67'),
  ('sat.math', 'problem-solving', null, 'mcq', null, 'A price rises by 20% and then falls by 20%. Compared with the original, the final price is:', '[{"text":"The same"},{"text":"4% lower"},{"text":"4% higher"},{"text":"2% lower"}]'::jsonb, 1, '1.2 × 0.8 = 0.96, so the price is 4% lower than it started.', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'pending_review', 'Written for Chapter; answers checked during authoring. No skill match: check topic and syllabus fit before publishing.', 'ed0db45bba029db5c6f45b3a579dceec'),
  ('sat.math', 'problem-solving', 'sat.math/problem-solving/statistics', 'mcq', null, 'Mean of {2, 4, 6, 8, 10}:', '[{"text":"5"},{"text":"30"},{"text":"4"},{"text":"6"}]'::jsonb, 3, 'Mean = (2+4+6+8+10)/5 = 30/5 = 6', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'fceb8c604712efdcae400bd65ce4557e'),
  ('sat.math', 'problem-solving', null, 'mcq', null, 'Mode of {1, 2, 2, 3, 4}:', '[{"text":"1"},{"text":"3"},{"text":"4"},{"text":"2"}]'::jsonb, 3, 'Mode is the value that appears most often. 2 appears twice, all others once.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'pending_review', 'Imported from the original Chapter app. No skill match: check topic and syllabus fit before publishing.', '9609e6964fb9eb3a76a8349068bd7440'),
  ('sat.math', 'problem-solving', 'sat.math/problem-solving/statistics', 'mcq', null, 'Standard deviation measures:', '[{"text":"Average value"},{"text":"Most common value"},{"text":"Middle value"},{"text":"Spread of data around the mean"}]'::jsonb, 3, 'Standard deviation measures how much data points vary from the mean. Higher SD = more spread out.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '307835dc997f9547ca95325d3063aaa9'),
  ('sat.math', 'problem-solving', null, 'mcq', null, 'If P(A) = 0.3 and P(B) = 0.5 and A,B are independent, P(A and B) = ?', '[{"text":"0.8"},{"text":"0.15"},{"text":"0.2"},{"text":"0.5"}]'::jsonb, 1, 'For independent events: P(A∩B) = P(A) × P(B) = 0.3 × 0.5 = 0.15', 4, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'pending_review', 'Imported from the original Chapter app. No skill match: check topic and syllabus fit before publishing.', '3f8ede7a37d6228907ed9e05cea0cfb3'),
  ('sat.math', 'geometry-trig', 'sat.math/geometry-trig/right-triangles', 'mcq', null, 'A right triangle has legs of length 9 and 12. What is the length of the hypotenuse?', '[{"text":"13"},{"text":"15"},{"text":"17"},{"text":"21"}]'::jsonb, 1, '√(9² + 12²) = √225 = 15 (a 3-4-5 triangle scaled by 3).', 2, 'apply', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '679f273dbc0f228fcc34f566a929ca00'),
  ('sat.math', 'geometry-trig', 'sat.math/geometry-trig/right-triangles', 'mcq', null, 'In a right triangle, sin A = 3/5. What is cos A?', '[{"text":"3/4"},{"text":"4/5"},{"text":"5/3"},{"text":"5/4"}]'::jsonb, 1, 'Opposite 3, hypotenuse 5, so adjacent is 4 and cos A = 4/5.', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'e2c26006d413adac9e67d34d61364462'),
  ('sat.math', 'geometry-trig', 'sat.math/geometry-trig/circles', 'mcq', null, 'A circle has equation (x − 2)² + (y + 5)² = 49. What are its centre and radius?', '[{"text":"(2, −5), radius 7"},{"text":"(−2, 5), radius 7"},{"text":"(2, −5), radius 49"},{"text":"(−2, 5), radius 49"}]'::jsonb, 0, 'Standard form (x − h)² + (y − k)² = r² gives centre (2, −5) and r = √49 = 7.', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'd9e8063acc7d29c8b834905f3a275766'),
  ('sat.math', 'geometry-trig', 'sat.math/geometry-trig/area-volume', 'mcq', null, 'Two angles of a triangle measure 48° and 67°. What is the third angle?', '[{"text":"55°"},{"text":"65°"},{"text":"75°"},{"text":"115°"}]'::jsonb, 1, '180° − 48° − 67° = 65°.', 2, 'apply', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'ff15f49a92eeb123180cb9689840a4e5'),
  ('sat.math', 'geometry-trig', 'sat.math/geometry-trig/area-volume', 'mcq', null, 'A cylinder has radius 3 cm and height 10 cm. What is its volume?', '[{"text":"30π cm³"},{"text":"60π cm³"},{"text":"90π cm³"},{"text":"300π cm³"}]'::jsonb, 2, 'V = πr²h = π × 9 × 10 = 90π cm³.', 2, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '9b9ac5911e7099ade5ff6e5ba8bcc5f3'),
  ('sat.math', 'geometry-trig', 'sat.math/geometry-trig/circles', 'mcq', null, 'An arc subtends a central angle of 60° in a circle of radius 12. What is the arc length?', '[{"text":"2π"},{"text":"4π"},{"text":"6π"},{"text":"12π"}]'::jsonb, 1, 'Arc length = (60/360) × 2π × 12 = 4π.', 3, 'apply', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '1448dbaf16bcc0a57c36abaacbd4d24d'),
  ('sat.math', 'geometry-trig', 'sat.math/geometry-trig/area-volume', 'mcq', null, 'Triangles ABC and DEF are similar with scale factor 3 (DEF is larger). If the area of ABC is 10, what is the area of DEF?', '[{"text":"30"},{"text":"60"},{"text":"90"},{"text":"270"}]'::jsonb, 2, 'Areas scale by the square of the scale factor: 10 × 3² = 90.', 4, 'apply', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '370ce7a74ad0cb58ef31bb00244d3421'),
  ('sat.math', 'geometry-trig', 'sat.math/geometry-trig/trigonometry', 'mcq', null, 'What is 150° in radians?', '[{"text":"π/6"},{"text":"5π/6"},{"text":"3π/4"},{"text":"5π/3"}]'::jsonb, 1, '150 × π/180 = 5π/6.', 3, 'recall', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'fda62194f7515275f742aaf2bfaebd08'),
  ('sat.math', 'geometry-trig', 'sat.math/geometry-trig/circles', 'mcq', null, 'Area of a circle with radius 5?', '[{"text":"10π"},{"text":"5π"},{"text":"25π"},{"text":"50π"}]'::jsonb, 2, 'A = πr² = π × 5² = 25π ≈ 78.54', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '330b2edd152e2a39f9a49aa46cd421e2'),
  ('sat.math', 'geometry-trig', 'sat.math/geometry-trig/right-triangles', 'mcq', null, 'In a right triangle, a=3, b=4. Find hypotenuse c.', '[{"text":"7"},{"text":"25"},{"text":"5"},{"text":"12"}]'::jsonb, 2, 'Pythagoras: c² = a² + b² = 9 + 16 = 25. c = 5. The 3-4-5 Pythagorean triple!', 2, 'apply', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'd7a54426530ec4c7ea75b5dcf5cb4b37'),
  ('sat.math', 'geometry-trig', null, 'mcq', null, 'Interior angles of any triangle sum to:', '[{"text":"90°"},{"text":"180°"},{"text":"270°"},{"text":"360°"}]'::jsonb, 1, 'All triangles: angle sum = 180°. Quadrilaterals = 360°. Regular polygon: (n−2)×180°', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'pending_review', 'Imported from the original Chapter app. No skill match: check topic and syllabus fit before publishing.', 'd65bf59a73bcccd616df2ec7f730798a'),
  ('sat.math', 'geometry-trig', null, 'mcq', null, 'Midpoint of (2,4) and (8,10) is:', '[{"text":"(6,14)"},{"text":"(3,5)"},{"text":"(4,6)"},{"text":"(5,7)"}]'::jsonb, 3, 'Midpoint = ((x₁+x₂)/2, (y₁+y₂)/2) = ((2+8)/2, (4+10)/2) = (5, 7)', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'pending_review', 'Imported from the original Chapter app. No skill match: check topic and syllabus fit before publishing.', 'f7adcaca8aa07bf1d063dde857b6b787'),
  ('sat.math', 'algebra', 'sat.math/algebra/linear-functions', 'mcq', null, 'Slope of the line y = 3x + 7 is:', '[{"text":"7"},{"text":"10"},{"text":"−3"},{"text":"3"}]'::jsonb, 3, 'In y = mx + c, m is the slope (gradient) and c is the y-intercept. Here m = 3.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'f9b85d9864d36934ba86a4b1dafc4a07'),
  ('sat.reading-writing', 'information-ideas', 'sat.reading-writing/information-ideas/central-ideas', 'mcq', null, 'Researchers found that honeybees exposed to low doses of a common pesticide took nearly twice as long to return to their hives as unexposed bees, though the exposed bees eventually found their way back.

Which choice best states the main finding?', '[{"text":"The pesticide kills honeybees."},{"text":"The pesticide slowed but did not prevent the bees’ return to their hives."},{"text":"Unexposed bees could not find their hives."},{"text":"Honeybees avoid flowers treated with pesticide."}]'::jsonb, 1, 'The text says exposed bees took longer but "eventually found their way back". Nothing supports death or avoidance.', 2, 'analyse', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'ecd6cafc45fae2dbf08de59fea2a2451'),
  ('sat.reading-writing', 'information-ideas', 'sat.reading-writing/information-ideas/command-of-evidence', 'mcq', null, 'Many historians once assumed that medieval peasants rarely travelled. However, records of pilgrimages and markets show that ordinary people regularly journeyed dozens of miles.

Which choice best describes the function of the second sentence?', '[{"text":"It offers evidence that challenges an earlier assumption."},{"text":"It restates the historians’ assumption."},{"text":"It explains why historians were correct."},{"text":"It introduces an unrelated topic."}]'::jsonb, 0, '"However" signals a contrast; the records are evidence against the older view.', 2, 'analyse', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '4c0fe308842d6a4d3fb67a8ea5b605b1'),
  ('sat.reading-writing', 'information-ideas', 'sat.reading-writing/information-ideas/inferences', 'mcq', null, 'A study of 1 200 teenagers found that those who slept at least eight hours scored higher on memory tests. The researchers cautioned that the study shows an association only.

Which statement is best supported by the text?', '[{"text":"Sleeping eight hours causes better memory."},{"text":"Teenagers who slept more tended to score higher, but the cause is not established."},{"text":"Memory tests are unreliable."},{"text":"Most teenagers sleep eight hours."}]'::jsonb, 1, 'The researchers explicitly limit the claim to an association, not causation.', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'caa2dd143c824fbc72cd8f0e6f235da8'),
  ('sat.reading-writing', 'information-ideas', 'sat.reading-writing/information-ideas/command-of-evidence', 'mcq', null, 'An ecologist claims that reintroducing wolves reduced overgrazing by deer in a national park.

Which finding would most directly support the claim?', '[{"text":"Wolves were first seen in the park in 1995."},{"text":"Deer numbers fell and young trees regrew along rivers after wolves returned."},{"text":"Tourists enjoy seeing wolves."},{"text":"Wolves also live in other parks."}]'::jsonb, 1, 'Only this choice links wolves to fewer deer and recovering vegetation, i.e. reduced overgrazing.', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '780c75c1ea2bc03543a1b235ee2dd4e3'),
  ('sat.reading-writing', 'information-ideas', 'sat.reading-writing/information-ideas/quantitative-evidence', 'mcq', null, 'In a table of average rainfall, City A receives 40 mm in June and 110 mm in October; City B receives 95 mm in June and 30 mm in October.

Which statement is supported by the data?', '[{"text":"City A is wetter than City B in every month."},{"text":"City B receives more rain than City A in June."},{"text":"Both cities are wettest in October."},{"text":"City B receives no rain in October."}]'::jsonb, 1, 'In June City B has 95 mm against City A’s 40 mm. The other choices contradict the numbers.', 2, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'e901f852a480f7111ef7dda49960601f'),
  ('sat.reading-writing', 'information-ideas', 'sat.reading-writing/information-ideas/inferences', 'mcq', null, 'The novelist wrote quickly, often finishing a chapter in a single night, yet she revised each manuscript so heavily that her editors joked about receiving "a new book" every draft.

Which choice best describes the novelist, based on the text?', '[{"text":"Careless about her work"},{"text":"Fast at drafting and thorough at revising"},{"text":"Unwilling to accept editing"},{"text":"Slow to write first drafts"}]'::jsonb, 1, 'She drafted quickly ("a chapter in a single night") and revised heavily.', 3, 'analyse', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '12e23ea617a1557013216d2a685329de'),
  ('sat.reading-writing', 'information-ideas', 'sat.reading-writing/information-ideas/central-ideas', 'mcq', null, 'The main purpose of a topic sentence is to:', '[{"text":"Conclude the paragraph"},{"text":"Provide a transition"},{"text":"Introduce the paragraph''s main idea"},{"text":"Give evidence"}]'::jsonb, 2, 'A topic sentence states the paragraph''s main idea — usually the first sentence. All other sentences support it.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'e482787a7bc8faeaf8113426fe4826b1'),
  ('sat.reading-writing', 'information-ideas', 'sat.reading-writing/information-ideas/central-ideas', 'mcq', null, '''Implicit'' meaning in a text means:', '[{"text":"Directly stated"},{"text":"Hidden or suggested, not stated directly"},{"text":"Repeated throughout"},{"text":"Found in the title"}]'::jsonb, 1, 'Implicit = implied/suggested. Explicit = directly stated. Good readers ''read between the lines'' for implicit meaning.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '76f5589fa7d50415b9dfd4d7f40dd056'),
  ('sat.reading-writing', 'information-ideas', 'sat.reading-writing/information-ideas/command-of-evidence', 'mcq', null, 'To infer means to:', '[{"text":"Copy directly"},{"text":"Work out meaning from clues"},{"text":"Skip a section"},{"text":"Count words"}]'::jsonb, 1, 'Inference is reading between the lines using evidence and clues.', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', 'd6f419c014601f6df3871aa50d0fd7e8'),
  ('sat.reading-writing', 'information-ideas', 'sat.reading-writing/information-ideas/central-ideas', 'mcq', null, 'Skimming a text means reading:', '[{"text":"Every word slowly"},{"text":"Quickly for the general idea"},{"text":"Only the last line"},{"text":"Backwards"}]'::jsonb, 1, 'Skimming = reading fast to get the gist; scanning = hunting for specific info.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '9782e742fb1af8a016bdbd39bdc8ca68'),
  ('sat.reading-writing', 'information-ideas', 'sat.reading-writing/information-ideas/central-ideas', 'mcq', null, 'The ''tone'' of a passage refers to the writer''s:', '[{"text":"Handwriting"},{"text":"Attitude toward the subject"},{"text":"Word count"},{"text":"Font"}]'::jsonb, 1, 'Tone is the writer''s attitude (e.g. sarcastic, formal, hopeful).', 3, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '377f358817f724003d00f919d5f8117b'),
  ('sat.reading-writing', 'information-ideas', 'sat.reading-writing/information-ideas/central-ideas', 'mcq', null, 'A reliable source is one that is:', '[{"text":"Anonymous"},{"text":"Accurate and credible"},{"text":"Always shortest"},{"text":"Most colourful"}]'::jsonb, 1, 'Reliable sources are accurate, credible, and ideally verifiable.', 4, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '125dd60eeea0362e71cc3722eeba548c'),
  ('sat.reading-writing', 'information-ideas', 'sat.reading-writing/information-ideas/central-ideas', 'mcq', null, '''Bias'' in a text means it:', '[{"text":"Presents all views equally"},{"text":"Favours one side unfairly"},{"text":"Has no opinion"},{"text":"Is fictional"}]'::jsonb, 1, 'Bias is a one-sided slant that favours a particular view.', 4, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '3598bb832932abae2b163774afab36de'),
  ('sat.reading-writing', 'information-ideas', 'sat.reading-writing/information-ideas/central-ideas', 'mcq', null, 'A summary should be:', '[{"text":"Longer than the original"},{"text":"A short version of the main points"},{"text":"Word-for-word"},{"text":"Only the title"}]'::jsonb, 1, 'A summary briefly captures the key points in fewer words.', 2, 'understand', 'all', array['legacy-bank']::text[], 'owned', 'Chapter legacy question bank (Whitespace Studio)', 'Proprietary: Whitespace Studio', 'owned', 'published', 'Imported from the original Chapter app.', '5d250dd1bdb14bb1eb7b45c56101d414'),
  ('sat.reading-writing', 'craft-structure', 'sat.reading-writing/craft-structure/words-in-context', 'mcq', null, 'The architect’s design was deliberately ______: every room served a clear purpose, and there was no decoration for its own sake.

Which word most logically completes the text?', '[{"text":"ornate"},{"text":"austere"},{"text":"chaotic"},{"text":"fragile"}]'::jsonb, 1, 'No decoration and a clear purpose for every room describe an austere (plain, severe) design.', 3, 'analyse', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'afb6687989793aa3f829cb37d592593a'),
  ('sat.reading-writing', 'craft-structure', 'sat.reading-writing/craft-structure/words-in-context', 'mcq', null, 'Although the scientist’s early results were promising, she remained ______, insisting on repeating the experiment before announcing anything.

Which word most logically completes the text?', '[{"text":"cautious"},{"text":"triumphant"},{"text":"indifferent"},{"text":"careless"}]'::jsonb, 0, 'Repeating the experiment before announcing shows caution; "although" sets up the contrast with promising results.', 2, 'analyse', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '9fa2b921a707536bc750e81bde4c94d4'),
  ('sat.reading-writing', 'craft-structure', 'sat.reading-writing/craft-structure/words-in-context', 'mcq', null, 'The critic described the film’s ending as "abrupt but earned."

As used here, "earned" most nearly means:', '[{"text":"paid for"},{"text":"justified by what came before"},{"text":"won in a contest"},{"text":"deserved as a salary"}]'::jsonb, 1, 'An "earned" ending is one the story has prepared for, even if it arrives suddenly.', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', '350deb39cfd3b32d29b22864ad3abd44'),
  ('sat.reading-writing', 'craft-structure', 'sat.reading-writing/craft-structure/cross-text', 'mcq', null, 'Text 1 argues that city gardens mainly benefit wildlife. Text 2 agrees they help wildlife but emphasises their role in bringing neighbours together.

How would the author of Text 2 most likely respond to Text 1?', '[{"text":"By rejecting the idea that gardens help wildlife"},{"text":"By adding that gardens also have important social benefits"},{"text":"By arguing gardens should be removed"},{"text":"By claiming wildlife prefers rural areas"}]'::jsonb, 1, 'Text 2 accepts the wildlife point and extends it with a social benefit.', 3, 'understand', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'e9b0a8decc9b41855d3a551b7122c489'),
  ('sat.reading-writing', 'craft-structure', 'sat.reading-writing/craft-structure/text-structure', 'mcq', null, 'The author begins by describing a crowded 1920s train station, then explains how the arrival of cars reduced rail travel, and ends with the station’s recent conversion into a museum.

Which choice best describes the overall structure?', '[{"text":"A comparison of two cities"},{"text":"A chronological account of a place’s changing role"},{"text":"An argument against cars"},{"text":"A list of museum exhibits"}]'::jsonb, 1, 'The text moves through time: busy station, decline, new use.', 2, 'analyse', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'd925c3fd1fb1fd5180bdcec859d3487b'),
  ('sat.reading-writing', 'craft-structure', 'sat.reading-writing/craft-structure/words-in-context', 'mcq', null, 'The negotiator’s reply was ______; it neither accepted nor rejected the offer, leaving both sides uncertain.

Which word most logically completes the text?', '[{"text":"emphatic"},{"text":"equivocal"},{"text":"hostile"},{"text":"generous"}]'::jsonb, 1, 'Equivocal means ambiguous; the reply committed to neither acceptance nor rejection.', 4, 'analyse', 'all', array['chapter-original']::text[], 'owned', 'Chapter original questions (2026)', 'Proprietary: Chapter', 'owned', 'published', 'Written for Chapter; answers checked during authoring.', 'e49d022497b5ee96f5156635432b73e3'),
  ('sat.reading-writing', 'expression-ideas', 'sat.reading-writing/expression-ideas/transitions', 'mcq', null, 'Solar panels have become far cheaper over the past decade. ______, many households that once found them unaffordable are now installing them.

